  "Submit a correction for a missed or incorrect punch. Your manager will review and approve within the regularization cutoff window (7 days after month end).": "വിട്ടുപോയതോ തെറ്റായതോ ആയ പഞ്ചിന് തിരുത്തൽ സമർപ്പിക്കുക. ക്രമപ്പെടുത്തലിനുള്ള അവസാന കാലാവധിക്കുള്ളിൽ (മാസാവസാനം കഴിഞ്ഞ് 7 ദിവസം) നിങ്ങളുടെ മാനേജർ പരിശോധിച്ച് അംഗീകരിക്കും.",
