  // Home banner, tax notices and late-login text
  "You are viewing this workspace read-only. Nothing you do here is saved.": "നിങ്ങൾ ഈ വർക്ക്സ്പേസ് കാണാൻ മാത്രമായി തുറന്നിരിക്കുന്നു. ഇവിടെ നിങ്ങൾ ചെയ്യുന്ന ഒന്നും സേവ് ചെയ്യപ്പെടില്ല.",
  "Requests are recorded against your employee record and routed to the approver shown on each one.": "അപേക്ഷകൾ നിങ്ങളുടെ ജീവനക്കാരുടെ രേഖയിൽ രേഖപ്പെടുത്തുകയും ഓരോന്നിലും കാണിച്ചിട്ടുള്ള അംഗീകരിക്കുന്നയാൾക്ക് അയയ്ക്കുകയും ചെയ്യുന്നു.",
