  "Your {year} regime and declarations were approved. Further changes follow payroll approval.": "നിങ്ങളുടെ {year}-ലെ നികുതി സമ്പ്രദായവും പ്രഖ്യാപനങ്ങളും അംഗീകരിച്ചു. തുടർന്നുള്ള മാറ്റങ്ങൾ പേറോൾ അംഗീകാരത്തെ അനുസരിച്ചായിരിക്കും.",
