  "Cards": "കാർഡുകൾ",
  "Changes employees ask HR to make to their profile. Everyone who answers HR Help tickets, and any full-access user, sees all of them.": "ജീവനക്കാർ തങ്ങളുടെ പ്രൊഫൈലിൽ വരുത്താൻ എച്ച്ആറിനോട് ആവശ്യപ്പെടുന്ന മാറ്റങ്ങൾ. എച്ച്ആർ സഹായ ടിക്കറ്റുകൾക്ക് മറുപടി നൽകുന്ന എല്ലാവർക്കും പൂർണ്ണ ആക്സസ് ഉള്ള ഏതൊരു ഉപയോക്താവിനും ഇവ എല്ലാം കാണാം.",
  "Counts show only what the server lets you see. Onboarding approvals are in Review & Onboarding, and bank-change requests are in the employee record; they are not part of this list.": "സെർവർ നിങ്ങളെ കാണാൻ അനുവദിക്കുന്നവ മാത്രമേ എണ്ണത്തിൽ കാണിക്കൂ. ഓൺബോർഡിംഗ് അംഗീകാരങ്ങൾ “അവലോകനവും ഓൺബോർഡിംഗും” എന്നതിലും ബാങ്ക് മാറ്റ അപേക്ഷകൾ ജീവനക്കാരുടെ രേഖയിലുമാണ്; അവ ഈ പട്ടികയുടെ ഭാഗമല്ല.",
  "Cycle sign-off for your team or payroll scope. Open the tab to see what is due.": "നിങ്ങളുടെ ടീമിനോ പേറോൾ പരിധിക്കോ ഉള്ള സൈക്കിൾ അംഗീകാരം. എന്താണ് തീർക്കാനുള്ളതെന്ന് കാണാൻ ടാബ് തുറക്കുക.",
  "Employees assigned to you; with no assigned HR, employees on your branch. A full-access user sees all.": "നിങ്ങൾക്ക് നിയോഗിച്ച ജീവനക്കാർ; എച്ച്ആറെ നിയോഗിച്ചിട്ടില്ലെങ്കിൽ നിങ്ങളുടെ ബ്രാഞ്ചിലെ ജീവനക്കാർ. പൂർണ്ണ ആക്സസ് ഉള്ള ഉപയോക്താവിന് എല്ലാം കാണാം.",
