  "9 hours": "9 മണിക്കൂർ",
  "A fallback punch must still be from inside the office geofence. It is flagged on the punch and recorded in the Audit Log.": "ഫാൾബാക്ക് പഞ്ചും ഓഫീസ് ജിയോഫെൻസിനുള്ളിൽ നിന്നായിരിക്കണം. ഇത് പഞ്ചിൽ ഫ്ലാഗ് ചെയ്യുകയും ഓഡിറ്റ് ലോഗിൽ രേഖപ്പെടുത്തുകയും ചെയ്യും.",
