  "Discard Changes": "മാറ്റങ്ങൾ ഉപേക്ഷിക്കുക",
  "Early Exit Grace": "നേരത്തെ ഇറങ്ങാനുള്ള ഗ്രേസ്",
  "Every message (the clock-in error, the Profile page, the Face ID Registrations screen, the hire screen and the welcome email) follows this choice.": "എല്ലാ സന്ദേശങ്ങളും (ക്ലോക്ക്-ഇൻ പിശക്, പ്രൊഫൈൽ പേജ്, Face ID രജിസ്ട്രേഷൻ സ്ക്രീൻ, നിയമന സ്ക്രീൻ, സ്വാഗത ഇമെയിൽ) ഈ തിരഞ്ഞെടുപ്പ് പിന്തുടരും.",
  "Face ID registration is": "Face ID രജിസ്ട്രേഷൻ",
  "Face ID Verification": "Face ID വെരിഫിക്കേഷൻ",
  "Face ID verification is": "Face ID വെരിഫിക്കേഷൻ",
  "for every employee. Every web punch needs a live face match against an approved Face ID; until one exists, web clock-in/out is blocked unless you allow the fallback below.": "എല്ലാ ജീവനക്കാർക്കും. ഓരോ വെബ് പഞ്ചിനും അംഗീകരിച്ച Face ID-യുമായി തത്സമയ ഫേസ് മാച്ച് വേണം; അത് ഉണ്ടാകുന്നതുവരെ, താഴെയുള്ള ഫാൾബാക്ക് അനുവദിച്ചില്ലെങ്കിൽ വെബ് ക്ലോക്ക്-ഇൻ/ഔട്ട് തടയപ്പെടും.",
  "Forgive late arrival when full hours are completed": "മുഴുവൻ മണിക്കൂറും പൂർത്തിയാക്കിയാൽ വൈകിയുള്ള വരവ് ഒഴിവാക്കുക",
  "Grace Period (min)": "ഗ്രേസ് കാലയളവ് (മിനിറ്റ്)",
  "Half-Day Limit (hours or fewer)": "അർധ ദിവസ പരിധി (മണിക്കൂർ അല്ലെങ്കിൽ അതിൽ കുറവ്)",
  "How many days back an employee can request work from home. Not allowed (recommended): today or a later date only, because an approved request for a past day relabels that day after the fact and the home-location check cannot be met.": "ഒരു ജീവനക്കാരന് എത്ര ദിവസം പിന്നോട്ട് വർക്ക് ഫ്രം ഹോം അപേക്ഷിക്കാം. അനുവദിക്കില്ല (ശുപാർശ ചെയ്യുന്നത്): ഇന്നോ പിന്നീടുള്ള തീയതിയോ മാത്രം, കാരണം കഴിഞ്ഞ ദിവസത്തെ അപേക്ഷ അംഗീകരിച്ചാൽ ആ ദിവസത്തിന്റെ നില പിന്നീട് മാറ്റപ്പെടും, വീട്ടിലെ ലൊക്കേഷൻ പരിശോധന പാലിക്കാനും കഴിയില്ല.",
  "HR only": "എച്ച്ആർ മാത്രം",
