  "Notify": "അറിയിക്കുക",
  "Notify HR and the manager when an employee is absent for N+ consecutive working days without approved leave.": "അംഗീകൃത ലീവില്ലാതെ ഒരു ജീവനക്കാരൻ തുടർച്ചയായി N+ പ്രവൃത്തി ദിവസം ഹാജരാകാതിരുന്നാൽ എച്ച്ആറിനെയും മാനേജരെയും അറിയിക്കുക.",
  "off": "ഓഫ്",
  "Off (recommended): a finished day of the half-day limit or fewer is a Half Day; a day above it but short of the full-day minimum stays Present and is shown as “hours not completed” with the minutes short. On: every day below the full-day minimum is a Half Day.": "ഓഫ് (ശുപാർശ ചെയ്യുന്നത്): അർധ ദിവസ പരിധിയോ അതിൽ കുറവോ ജോലി ചെയ്ത ദിവസം അർധ ദിവസമാണ്; അതിന് മുകളിലും എന്നാൽ മുഴുവൻ ദിവസത്തെ കുറഞ്ഞ സമയത്തിൽ താഴെയുമുള്ള ദിവസം ഹാജർ ആയിത്തന്നെ തുടരും, കുറവുള്ള മിനിറ്റുകളോടെ “മണിക്കൂർ പൂർത്തിയായില്ല” എന്ന് കാണിക്കും. ഓൺ: മുഴുവൻ ദിവസത്തെ കുറഞ്ഞ സമയത്തിൽ താഴെയുള്ള എല്ലാ ദിവസവും അർധ ദിവസമാണ്.",
  "OT Multiplier — Holiday": "ഓവർടൈം ഗുണിതം — അവധി ദിനം",
  "OT Multiplier — Regular": "ഓവർടൈം ഗുണിതം — സാധാരണ",
