  "Someone who arrives after the grace period but works the full-day hours is marked Present and gets no late mark. The late arrival stays as a note.": "ഗ്രേസ് കാലയളവിന് ശേഷം എത്തിയെങ്കിലും മുഴുവൻ ദിവസത്തെ മണിക്കൂർ ജോലി ചെയ്യുന്നയാളെ ഹാജരായതായി രേഖപ്പെടുത്തും, ലേറ്റ് മാർക്ക് ലഭിക്കില്ല. വൈകിയുള്ള വരവ് ഒരു കുറിപ്പായി നിലനിൽക്കും.",
  "Treat every day below the full day as a Half Day": "മുഴുവൻ ദിവസത്തിൽ താഴെയുള്ള എല്ലാ ദിവസവും അർധ ദിവസമായി കണക്കാക്കുക",
