  "Worked hours after the break is deducted. Shift length minus the break makes overtime start exactly at shift end.": "ഇടവേള കുറച്ചശേഷമുള്ള ജോലി സമയം. ഷിഫ്റ്റ് ദൈർഘ്യത്തിൽ നിന്ന് ഇടവേള കുറയ്ക്കുമ്പോൾ ഓവർടൈം കൃത്യമായി ഷിഫ്റ്റ് അവസാനത്തിൽ തുടങ്ങും.",
