  "Shown once the shift end and grace period have passed without a clock-out.": "ക്ലോക്ക്-ഔട്ട് ഇല്ലാതെ ഷിഫ്റ്റ് അവസാനവും ഗ്രേസ് കാലയളവും കഴിഞ്ഞാൽ ഇത് കാണിക്കും.",
  "All Patterns": "എല്ലാ പാറ്റേണുകളും",
  "Applies to every active employee matching the filters below — resolved on the server, so no employee list needs to load into the browser first.": "താഴെയുള്ള ഫിൽട്ടറുകൾക്ക് യോജിക്കുന്ന എല്ലാ സജീവ ജീവനക്കാർക്കും ബാധകം — സെർവറിൽ തീരുമാനിക്കുന്നതിനാൽ ആദ്യം ബ്രൗസറിൽ ജീവനക്കാരുടെ പട്ടിക ലോഡ് ചെയ്യേണ്ടതില്ല.",
  "Assign to Matching Employees": "യോജിക്കുന്ന ജീവനക്കാർക്ക് നിയോഗിക്കുക",
