  "Failed to assign pattern.": "പാറ്റേൺ നിയോഗിക്കാനായില്ല.",
  "Past attendance is never affected — this pattern applies from the effective date forward only.": "കഴിഞ്ഞ ഹാജറിനെ ഒരിക്കലും ബാധിക്കില്ല — ഈ പാറ്റേൺ പ്രാബല്യ തീയതി മുതൽ മുന്നോട്ട് മാത്രമേ ബാധകമാകൂ.",
  "Select pattern…": "പാറ്റേൺ തിരഞ്ഞെടുക്കുക…",
  "the selected pattern": "തിരഞ്ഞെടുത്ത പാറ്റേൺ",
  "This assigns \"{pattern}\" effective {date} to every active employee matching: {scope}. The exact number of employees affected is resolved on the server and isn't known until this runs.": "ഇത് “{pattern}” എന്ന പാറ്റേൺ {date} മുതൽ പ്രാബല്യത്തിൽ, ഇവയ്ക്ക് യോജിക്കുന്ന എല്ലാ സജീവ ജീവനക്കാർക്കും നിയോഗിക്കുന്നു: {scope}. ബാധിക്കുന്ന ജീവനക്കാരുടെ കൃത്യമായ എണ്ണം സെർവറിലാണ് നിശ്ചയിക്കുന്നത്, ഇത് പ്രവർത്തിക്കുന്നതുവരെ അറിയില്ല.",
  "Try clearing a filter above.": "മുകളിലെ ഒരു ഫിൽട്ടർ നീക്കി നോക്കുക.",
  "Weekly Off Pattern": "ആഴ്ച അവധി പാറ്റേൺ",
  "Weekly off pattern assigned to {count} employee(s).": "ആഴ്ച അവധി പാറ്റേൺ {count} ജീവനക്കാർക്ക് നിയോഗിച്ചു.",
  "Weekly off pattern assigned to {name}.": "ആഴ്ച അവധി പാറ്റേൺ {name}-ന് നിയോഗിച്ചു.",
  "Which weekly off pattern each employee follows. A new pattern applies from its effective date forward.": "ഓരോ ജീവനക്കാരനും ഏത് ആഴ്ച അവധി പാറ്റേൺ പിന്തുടരുന്നു. പുതിയ പാറ്റേൺ അതിന്റെ പ്രാബല്യ തീയതി മുതൽ മുന്നോട്ട് ബാധകമാകും.",
  "\"{name}\" will be deactivated. Employees currently assigned this pattern keep it until reassigned — history is preserved.": "“{name}” നിഷ്ക്രിയമാക്കും. നിലവിൽ ഈ പാറ്റേൺ നിയോഗിച്ചിട്ടുള്ള ജീവനക്കാർക്ക് വീണ്ടും നിയോഗിക്കുന്നതുവരെ ഇത് തുടരും — ചരിത്രം സംരക്ഷിക്കപ്പെടും.",
