  "Configure reusable weekly-off schedules and assign them to employees from Attendance & Time → Weekly Off Assignment.": "വീണ്ടും ഉപയോഗിക്കാവുന്ന ആഴ്ച അവധി ഷെഡ്യൂളുകൾ ക്രമീകരിക്കുക, ഹാജരും സമയവും → ആഴ്ചതോറുമുള്ള അവധി നിശ്ചയിക്കൽ എന്നതിൽ നിന്ന് ജീവനക്കാർക്ക് നിയോഗിക്കുക.",
