  "They currently manage {count} employees — that reporting line won't be reassigned automatically.": "അവർ നിലവിൽ {count} ജീവനക്കാരെ നയിക്കുന്നു — ആ റിപ്പോർട്ടിംഗ് ബന്ധം സ്വയമേവ മാറ്റി നിയോഗിക്കില്ല.",
  "They're the assigned HR for {count} employee — that assignment won't be reassigned automatically.": "അവർ {count} ജീവനക്കാരന്റെ നിയോഗിച്ച എച്ച്ആർ ആണ് — ആ നിയോഗം സ്വയമേവ മാറ്റി നൽകില്ല.",
