  "{branchName} was updated and its Company Code Admin was assigned.": "{branchName} അപ്ഡേറ്റ് ചെയ്യുകയും അതിന്റെ കമ്പനി കോഡ് അഡ്മിനെ നിയോഗിക്കുകയും ചെയ്തു.",
  "{branchName} was updated and its Company Code Admin was invited by email.": "{branchName} അപ്ഡേറ്റ് ചെയ്യുകയും അതിന്റെ കമ്പനി കോഡ് അഡ്മിനെ ഇമെയിൽ വഴി ക്ഷണിക്കുകയും ചെയ്തു.",
  "{branchName} was updated, but assigning its Company Code Admin failed: {reason} — use the Employees page instead.": "{branchName} അപ്ഡേറ്റ് ചെയ്തു, പക്ഷേ അതിന്റെ കമ്പനി കോഡ് അഡ്മിനെ നിയോഗിക്കാനായില്ല: {reason} — പകരം ജീവനക്കാർ പേജ് ഉപയോഗിക്കുക.",
  "{branchName} was updated.": "{branchName} അപ്ഡേറ്റ് ചെയ്തു.",
