  "Nominees are chosen from this list, and the parents' names on step 1 are filled from it. Add family before setting nominations.": "നോമിനികളെ ഈ പട്ടികയിൽ നിന്ന് തിരഞ്ഞെടുക്കുന്നു, ഘട്ടം 1-ലെ മാതാപിതാക്കളുടെ പേരുകളും ഇതിൽ നിന്ന് പൂരിപ്പിക്കുന്നു. നോമിനേഷൻ നൽകുന്നതിന് മുമ്പ് കുടുംബാംഗങ്ങളെ ചേർക്കുക.",
  "Not required of a private employer. Collect only where a government, PSU or aided establishment must report it, or a state incentive scheme requires it. Self-declared, and hidden from reporting managers.": "സ്വകാര്യ തൊഴിലുടമയ്ക്ക് ആവശ്യമില്ല. സർക്കാർ, പൊതുമേഖലാ സ്ഥാപനം, അല്ലെങ്കിൽ എയ്ഡഡ് സ്ഥാപനം ഇത് റിപ്പോർട്ട് ചെയ്യേണ്ടിവരുമ്പോൾ, അല്ലെങ്കിൽ ഒരു സംസ്ഥാന പ്രോത്സാഹന പദ്ധതിക്ക് ആവശ്യമാകുമ്പോൾ മാത്രം ശേഖരിക്കുക. സ്വയം പ്രഖ്യാപിച്ചത്, റിപ്പോർട്ടിംഗ് മാനേജർമാരിൽ നിന്ന് മറച്ചിരിക്കുന്നു.",
  "Nothing outstanding": "തീർപ്പാക്കാൻ ഒന്നുമില്ല",
  "Only required if a nominee above is under 18.": "മുകളിലെ ഒരു നോമിനിക്ക് 18 വയസ്സിൽ താഴെയാണെങ്കിൽ മാത്രം ആവശ്യമാണ്.",
  "OPTIONAL, not yet stored post-hire": "ഓപ്ഷണൽ, നിയമനത്തിന് ശേഷം ഇതുവരെ സൂക്ഷിച്ചിട്ടില്ല",
  "Place of birth": "ജനന സ്ഥലം",
