  "Required for EPF Form 2. Nominees are picked from the family list, so a name is only typed once. Each scheme should total 100%.": "EPF ഫോം 2-ന് ആവശ്യമാണ്. നോമിനികളെ കുടുംബ പട്ടികയിൽ നിന്ന് തിരഞ്ഞെടുക്കുന്നതിനാൽ പേര് ഒരിക്കൽ മാത്രം ടൈപ്പ് ചെയ്താൽ മതി. ഓരോ പദ്ധതിയുടെയും ആകെ 100% ആയിരിക്കണം.",
