  "Leave empty for a fresher — total experience reads zero. Experience is counted up to the joining date.": "ഫ്രഷർ ആണെങ്കിൽ ഒഴിച്ചിടുക — ആകെ പ്രവൃത്തിപരിചയം പൂജ്യമായി കാണിക്കും. പ്രവൃത്തിപരിചയം ചേർന്ന തീയതി വരെ കണക്കാക്കുന്നു.",
