  "Monthly amounts derived from the annual CTC in Employment. Any earning can be overridden; Special Allowance balances back to CTC and the statutory rows recalculate.": "പ്രതിമാസ തുകകൾ തൊഴിൽ വിഭാഗത്തിലെ വാർഷിക CTC-യിൽ നിന്ന് കണക്കാക്കിയതാണ്. ഏത് വരുമാനവും മാറ്റാം; സ്പെഷ്യൽ അലവൻസ് CTC-യുമായി ഒത്തുപോകുന്ന വിധം ക്രമീകരിക്കുകയും നിയമപരമായ വരികൾ വീണ്ടും കണക്കാക്കുകയും ചെയ്യും.",
