  "Monthly amounts use the selected salary structure and effective date. Enabled structure components appear here; statutory contributions and deductions remain governed by payroll eligibility and statutory rules.": "പ്രതിമാസ തുകകൾ തിരഞ്ഞെടുത്ത ശമ്പള ഘടനയും പ്രാബല്യ തീയതിയും അനുസരിച്ചാണ്. പ്രവർത്തനക്ഷമമാക്കിയ ഘടകങ്ങൾ ഇവിടെ കാണാം; നിയമപരമായ വിഹിതങ്ങളും കിഴിവുകളും പേറോൾ അർഹതയും നിയമപരമായ ചട്ടങ്ങളും അനുസരിച്ചായിരിക്കും.",
  "No pay record exists for this employee yet.": "ഈ ജീവനക്കാരന് ഇതുവരെ ശമ്പള രേഖയില്ല.",
  "No salary structure applies to this employee. Add or activate one in Settings → Payroll Configuration → Salary Structures; pay components come from it.": "ഈ ജീവനക്കാരന് ബാധകമായ ശമ്പള ഘടനയില്ല. സെറ്റിംഗ്സ് → പേറോൾ കോൺഫിഗറേഷൻ → ശമ്പള ഘടനകളിൽ ഒന്ന് ചേർക്കുകയോ സജീവമാക്കുകയോ ചെയ്യുക; ശമ്പള ഘടകങ്ങൾ അതിൽ നിന്നാണ് വരുന്നത്.",
