  "Failed to record decision.": "തീരുമാനം രേഖപ്പെടുത്താനായില്ല.",
  "Full values are now shown in the Government IDs & Bank card above.": "പൂർണ്ണ മൂല്യങ്ങൾ ഇപ്പോൾ മുകളിലെ സർക്കാർ ഐഡികളും ബാങ്കും കാർഡിൽ കാണിക്കുന്നു.",
  "Government IDs & Bank · Masked": "സർക്കാർ ഐഡികളും ബാങ്കും · മറച്ചത്",
