  "Sensitive Data Control": "സെൻസിറ്റീവ് ഡാറ്റ നിയന്ത്രണം",
  "This account has no employee record on file (no employee number assigned), so employment, pay, statutory, and history details below are unavailable. This is expected for an admin/system login that was never onboarded as an employee — sign in as an onboarded employee to see a full record.": "ഈ അക്കൗണ്ടിന് ജീവനക്കാരുടെ രേഖയില്ല (ജീവനക്കാരുടെ നമ്പർ നിയോഗിച്ചിട്ടില്ല), അതിനാൽ താഴെയുള്ള തൊഴിൽ, ശമ്പളം, നിയമപരമായ, ചരിത്ര വിവരങ്ങൾ ലഭ്യമല്ല. ജീവനക്കാരനായി ഓൺബോർഡ് ചെയ്തിട്ടില്ലാത്ത അഡ്മിൻ/സിസ്റ്റം ലോഗിനിൽ ഇത് പ്രതീക്ഷിക്കാവുന്നതാണ് — പൂർണ്ണ രേഖ കാണാൻ ഓൺബോർഡ് ചെയ്ത ജീവനക്കാരനായി സൈൻ ഇൻ ചെയ്യുക.",
  "This employee submitted a bank detail change awaiting your review — their previous details remain active for payroll until you decide.": "ഈ ജീവനക്കാരൻ ബാങ്ക് വിവരങ്ങളിൽ മാറ്റം സമർപ്പിച്ചിട്ടുണ്ട്, അത് നിങ്ങളുടെ അവലോകനത്തിനായി കാത്തിരിക്കുന്നു — നിങ്ങൾ തീരുമാനിക്കുന്നത് വരെ അവരുടെ മുൻ വിവരങ്ങൾ പേറോളിന് സജീവമായി തുടരും.",
  "UAN": "UAN",
  "Click to choose the filled .xlsx file": "പൂരിപ്പിച്ച .xlsx ഫയൽ തിരഞ്ഞെടുക്കാൻ ക്ലിക്ക് ചെയ്യുക",
  "Confirm import of {count}": "{count} എണ്ണത്തിന്റെ ഇറക്കുമതി സ്ഥിരീകരിക്കുക",
  "Confirm.": "സ്ഥിരീകരിക്കുക.",
  "Download errors (Excel)": "പിശകുകൾ ഡൗൺലോഡ് ചെയ്യുക (Excel)",
  "Download template (.xlsx)": "ടെംപ്ലേറ്റ് ഡൗൺലോഡ് ചെയ്യുക (.xlsx)",
  "Download the template and fill it in.": "ടെംപ്ലേറ്റ് ഡൗൺലോഡ് ചെയ്ത് പൂരിപ്പിക്കുക.",
  "Each new employee then gets an activation email.": "തുടർന്ന് ഓരോ പുതിയ ജീവനക്കാരനും ഒരു ആക്ടിവേഷൻ ഇമെയിൽ ലഭിക്കും.",
  "Every row must be valid to start.": "തുടങ്ങാൻ ഓരോ വരിയും സാധുവായിരിക്കണം.",
