  "Fix the rows below (or download the error file), then upload again. Nothing has been created.": "താഴെയുള്ള വരികൾ ശരിയാക്കുക (അല്ലെങ്കിൽ പിശക് ഫയൽ ഡൗൺലോഡ് ചെയ്യുക), എന്നിട്ട് വീണ്ടും അപ്ലോഡ് ചെയ്യുക. ഒന്നും സൃഷ്ടിച്ചിട്ടില്ല.",
  "Import another file": "മറ്റൊരു ഫയൽ ഇറക്കുമതി ചെയ്യുക",
  "Import Employees from Excel": "Excel-ൽ നിന്ന് ജീവനക്കാരെ ഇറക്കുമതി ചെയ്യുക",
  "Starting…": "തുടങ്ങുന്നു…",
  "The employees are then created in the background, so you can close this window and come back: progress is saved.": "തുടർന്ന് ജീവനക്കാരെ പശ്ചാത്തലത്തിൽ സൃഷ്ടിക്കും, അതിനാൽ ഈ വിൻഡോ അടച്ച് പിന്നീട് വരാം: പുരോഗതി സേവ് ചെയ്തിട്ടുണ്ട്.",
  "Upload it and review the preview — nothing is created yet.": "അത് അപ്ലോഡ് ചെയ്ത് പ്രിവ്യൂ അവലോകനം ചെയ്യുക — ഇതുവരെ ഒന്നും സൃഷ്ടിച്ചിട്ടില്ല.",
