  "Please choose which field needs to change.": "ഏത് ഫീൽഡാണ് മാറ്റേണ്ടതെന്ന് ദയവായി തിരഞ്ഞെടുക്കുക.",
  "Please describe the reason in at least 10 characters.": "ദയവായി കാരണം കുറഞ്ഞത് 10 അക്ഷരങ്ങളിൽ വിവരിക്കുക.",
  "Profile correction": "പ്രൊഫൈൽ തിരുത്തൽ",
  "Reason for correction": "തിരുത്തലിനുള്ള കാരണം",
