  "Select a field…": "ഒരു ഫീൽഡ് തിരഞ്ഞെടുക്കുക…",
  "Attendance, leave and expenses open from your joining date. You can complete onboarding now.": "ഹാജർ, ലീവ്, ചെലവുകൾ എന്നിവ നിങ്ങൾ ജോലിയിൽ ചേരുന്ന തീയതി മുതൽ തുറക്കും. ഇപ്പോൾ നിങ്ങൾക്ക് ഓൺബോർഡിംഗ് പൂർത്തിയാക്കാം.",
  "Change profile photo": "പ്രൊഫൈൽ ഫോട്ടോ മാറ്റുക",
  "Correction request submitted — track it under My Requests.": "തിരുത്തൽ അപേക്ഷ സമർപ്പിച്ചു — “എന്റെ അപേക്ഷകൾ” എന്നതിൽ ട്രാക്ക് ചെയ്യുക.",
  "DATE OF BIRTH": "ജനന തീയതി",
  "DATE OF JOINING": "ജോലിയിൽ ചേർന്ന തീയതി",
