  "This employee has not registered a Face ID. You can register it now, in person.": "ഈ ജീവനക്കാരൻ Face ID രജിസ്റ്റർ ചെയ്തിട്ടില്ല. നിങ്ങൾക്ക് ഇപ്പോൾ നേരിട്ട് രജിസ്റ്റർ ചെയ്യാം.",
  "This will replace {name}'s registered Face ID will be replaced by the new capture.": "ഇത് {name}-ന്റെ രജിസ്റ്റർ ചെയ്ത Face ID പുതിയ ക്യാപ്ചർ ഉപയോഗിച്ച് മാറ്റിസ്ഥാപിക്കും.",
  "Next page": "അടുത്ത പേജ്",
  "Previous page": "മുൻ പേജ്",
  "Search by name, email or ID": "പേര്, ഇമെയിൽ അല്ലെങ്കിൽ ഐഡി ഉപയോഗിച്ച് തിരയുക",
  "Search employees by name, email or ID": "പേര്, ഇമെയിൽ അല്ലെങ്കിൽ ഐഡി ഉപയോഗിച്ച് ജീവനക്കാരെ തിരയുക",
  "{percent}% registered": "{percent}% രജിസ്റ്റർ ചെയ്തു",
  "Everyone is registered": "എല്ലാവരും രജിസ്റ്റർ ചെയ്തിട്ടുണ്ട്",
  "Face ID coverage": "Face ID വ്യാപ്തി",
  "Filter employees by Face ID status": "Face ID നില അനുസരിച്ച് ജീവനക്കാരെ ഫിൽട്ടർ ചെയ്യുക",
  "of {total} employees registered": "{total} ജീവനക്കാരിൽ രജിസ്റ്റർ ചെയ്തവർ",
  "Show {count} not completed": "പൂർത്തിയാകാത്ത {count} എണ്ണം കാണിക്കുക",
  "Pending requests": "തീർപ്പാക്കാനുള്ള അപേക്ഷകൾ",
  "Register or update an employee's Face ID in person. It is approved immediately.": "ഒരു ജീവനക്കാരന്റെ Face ID നേരിട്ട് രജിസ്റ്റർ ചെയ്യുകയോ പുതുക്കുകയോ ചെയ്യുക. ഇത് ഉടൻ അംഗീകരിക്കും.",
  "{name}'s face ID is approved and active immediately — no further review needed.": "{name}-ന്റെ Face ID ഉടൻ അംഗീകരിച്ച് സജീവമാകും — കൂടുതൽ അവലോകനം ആവശ്യമില്ല.",
  "Camera access denied": "ക്യാമറ ആക്സസ് നിരസിച്ചു",
  "Capture wasn't clear enough": "ക്യാപ്ചർ വേണ്ടത്ര വ്യക്തമായിരുന്നില്ല",
  "Couldn't confirm they're live": "അവർ നേരിട്ട് ഉണ്ടെന്ന് സ്ഥിരീകരിക്കാനായില്ല",
  "Downloading face models (first time only)…": "ഫേസ് മോഡലുകൾ ഡൗൺലോഡ് ചെയ്യുന്നു (ആദ്യ തവണ മാത്രം)…",
  "Face ID registered!": "Face ID രജിസ്റ്റർ ചെയ്തു!",
  "Have the employee sit in front of this camera, then start — a quick liveness check confirms it's really them before it's saved.": "ജീവനക്കാരനെ ഈ ക്യാമറയ്ക്ക് മുന്നിൽ ഇരുത്തിയ ശേഷം ആരംഭിക്കുക — സേവ് ചെയ്യുന്നതിന് മുമ്പ് ഒരു ദ്രുത ലൈവ്നെസ് പരിശോധന അത് അവർ തന്നെയാണെന്ന് ഉറപ്പാക്കും.",
  "Please allow camera access in the browser prompt.": "ബ്രൗസർ ചോദിക്കുമ്പോൾ ദയവായി ക്യാമറ ആക്സസ് അനുവദിക്കുക.",
  "Please try again.": "ദയവായി വീണ്ടും ശ്രമിക്കുക.",
  "Preparing face recognition": "ഫേസ് തിരിച്ചറിയൽ ഒരുക്കുന്നു",
  "Register {name}'s face": "{name}-ന്റെ മുഖം രജിസ്റ്റർ ചെയ്യുക",
  "Register Face ID — {name}": "Face ID രജിസ്റ്റർ ചെയ്യുക — {name}",
  "Registering a face ID needs camera access. Allow it for this site in your browser's settings, then try again.": "Face ID രജിസ്റ്റർ ചെയ്യാൻ ക്യാമറ ആക്സസ് ആവശ്യമാണ്. നിങ്ങളുടെ ബ്രൗസർ സെറ്റിംഗ്സിൽ ഈ സൈറ്റിന് അനുവദിച്ച ശേഷം വീണ്ടും ശ്രമിക്കുക.",
  "Registering face ID…": "Face ID രജിസ്റ്റർ ചെയ്യുന്നു…",
  "Registration needs both a natural blink and a slight head turn, and we didn't see both in time. Make sure they're well-lit and centered, then try again.": "രജിസ്ട്രേഷന് സ്വാഭാവികമായ കണ്ണ് ചിമ്മലും ചെറിയ തല തിരിക്കലും ആവശ്യമാണ്, രണ്ടും കൃത്യസമയത്ത് കണ്ടില്ല. വെളിച്ചം നന്നായി ഉണ്ടെന്നും മധ്യത്തിലാണെന്നും ഉറപ്പാക്കി വീണ്ടും ശ്രമിക്കുക.",
  "Requesting camera access": "ക്യാമറ ആക്സസ് അഭ്യർഥിക്കുന്നു",
  "Saving": "സേവ് ചെയ്യുന്നു",
  "Something went wrong": "എന്തോ കുഴപ്പം സംഭവിച്ചു",
  "This will replace their currently registered face ID. Position them in front of the camera and start when ready.": "ഇത് അവരുടെ നിലവിൽ രജിസ്റ്റർ ചെയ്ത Face ID മാറ്റിസ്ഥാപിക്കും. അവരെ ക്യാമറയ്ക്ക് മുന്നിൽ നിർത്തി തയ്യാറാകുമ്പോൾ ആരംഭിക്കുക.",
  "Try Again": "വീണ്ടും ശ്രമിക്കുക",
  "Update {name}'s face": "{name}-ന്റെ മുഖം പുതുക്കുക",
  "Update Face ID — {name}": "Face ID പുതുക്കുക — {name}",
  "We couldn't get a reliably clear capture — this becomes their permanent face ID reference, so it's worth getting right. Try better lighting and have them hold steady.": "വിശ്വസനീയമായി വ്യക്തമായ ക്യാപ്ചർ ലഭിച്ചില്ല — ഇതാണ് അവരുടെ സ്ഥിരമായ Face ID റഫറൻസ് ആകുന്നത്, അതിനാൽ ശരിയായി എടുക്കേണ്ടതാണ്. മെച്ചപ്പെട്ട വെളിച്ചം നൽകി അനങ്ങാതെ നിൽക്കാൻ പറയുക.",
  "Contact an HR administrator if you believe this is a mistake.": "ഇതൊരു തെറ്റാണെന്ന് തോന്നുന്നുവെങ്കിൽ എച്ച്ആർ അഡ്മിനിസ്ട്രേറ്ററെ ബന്ധപ്പെടുക.",
  "You don't have permission to manage face ID registrations": "Face ID രജിസ്ട്രേഷനുകൾ കൈകാര്യം ചെയ്യാൻ നിങ്ങൾക്ക് അനുമതിയില്ല",
  "{count} PIN codes in {district}": "{district}-ൽ {count} PIN കോഡുകൾ",
