  "Address line 2": "വിലാസം വരി 2",
  "Already filled in from the PIN code": "PIN കോഡിൽ നിന്ന് ഇതിനകം പൂരിപ്പിച്ചു",
  "Country": "രാജ്യം",
  "CURRENT ADDRESS": "നിലവിലെ വിലാസം",
  "Enter the 6-digit PIN code first. Suggest fills the state, district and city from it. You can also choose the state, then the district, then pick the PIN code from the list.": "ആദ്യം 6 അക്ക PIN കോഡ് നൽകുക. “നിർദ്ദേശിക്കുക” അതിൽ നിന്ന് സംസ്ഥാനം, ജില്ല, നഗരം എന്നിവ പൂരിപ്പിക്കും. സംസ്ഥാനം, പിന്നെ ജില്ല തിരഞ്ഞെടുത്ത് പട്ടികയിൽ നിന്ന് PIN കോഡ് തിരഞ്ഞെടുക്കാനും കഴിയും.",
  "Fill this in from the PIN code": "PIN കോഡിൽ നിന്ന് ഇത് പൂരിപ്പിക്കുക",
