  "Landmark": "അടയാളസ്ഥലം",
  "Near…": "സമീപം…",
  "Needs a 6-digit PIN code": "6 അക്ക PIN കോഡ് ആവശ്യമാണ്",
  "PERMANENT ADDRESS": "സ്ഥിര വിലാസം",
  "Permanent address is the same as current": "സ്ഥിര വിലാസം നിലവിലെ വിലാസം തന്നെയാണ്",
  "PIN code": "PIN കോഡ്",
  "Street, area": "തെരുവ്, പ്രദേശം",
  "Suggest": "നിർദ്ദേശിക്കുക",
  "That PIN code has no area name to suggest. Type the city.": "ആ PIN കോഡിന് നിർദ്ദേശിക്കാൻ പ്രദേശത്തിന്റെ പേരില്ല. നഗരം ടൈപ്പ് ചെയ്യുക.",
  "We could not find PIN code {pincode}. Check it, or choose the state and district yourself.": "PIN കോഡ് {pincode} കണ്ടെത്താനായില്ല. അത് പരിശോധിക്കുക, അല്ലെങ്കിൽ സംസ്ഥാനവും ജില്ലയും സ്വയം തിരഞ്ഞെടുക്കുക.",
  "Estimating…": "കണക്കാക്കുന്നു…",
  "New regime (115BAC)": "പുതിയ സമ്പ്രദായം (115BAC)",
  "Old regime": "പഴയ സമ്പ്രദായം",
  "Set an Annual fixed CTC on the Employment step first — the earnings breakdown estimates from that.": "ആദ്യം തൊഴിൽ ഘട്ടത്തിൽ വാർഷിക സ്ഥിര CTC നിശ്ചയിക്കുക — വരുമാന വിശദാംശം അതിൽ നിന്നാണ് കണക്കാക്കുന്നത്.",
  "{count} files": "{count} ഫയലുകൾ",
  "+ {count} more attached in Education & experience": "+ വിദ്യാഭ്യാസവും പരിചയവും എന്നതിൽ {count} എണ്ണം കൂടി ഘടിപ്പിച്ചിട്ടുണ്ട്",
  "attached in Education & experience": "വിദ്യാഭ്യാസവും പരിചയവും എന്നതിൽ ഘടിപ്പിച്ചിട്ടുണ്ട്",
  "In progress": "പുരോഗമിക്കുന്നു",
