  "+ Add emergency contact": "+ അടിയന്തര ബന്ധപ്പെടൽ ചേർക്കുക",
  "EMERGENCY CONTACT {number}": "അടിയന്തര ബന്ധപ്പെടൽ {number}",
  "EMERGENCY CONTACTS": "അടിയന്തര ബന്ധപ്പെടലുകൾ",
  "ADD": "ചേർക്കുക",
  "Could not upload this photo.": "ഈ ഫോട്ടോ അപ്ലോഡ് ചെയ്യാനായില്ല.",
  "JPG or PNG — resized automatically to fit. Cropped to a circle on ID cards and reports.": "JPG അല്ലെങ്കിൽ PNG — യോജിക്കുന്ന വലുപ്പത്തിലേക്ക് സ്വയം മാറ്റും. ഐഡി കാർഡുകളിലും റിപ്പോർട്ടുകളിലും വൃത്താകൃതിയിൽ മുറിക്കും.",
  "PHOTO": "ഫോട്ടോ",
  "Auto-assign": "സ്വയം നിയോഗിക്കുക",
  "Company code": "കമ്പനി കോഡ്",
  "Credited from the leave policy (Settings > Leave policy) by Company Code, gender and service period.": "കമ്പനി കോഡ്, ലിംഗം, സേവന കാലയളവ് എന്നിവ അനുസരിച്ച് ലീവ് നയത്തിൽ നിന്ന് (സെറ്റിംഗ്സ് > ലീവ് നയം) വരവുവെക്കുന്നു.",
  "e.g. 800000": "ഉദാ. 800000",
  "Employee number reserved: {id}. Changing this reserves a new number for the new type.": "ജീവനക്കാരുടെ നമ്പർ നീക്കിവച്ചു: {id}. ഇത് മാറ്റിയാൽ പുതിയ തരത്തിന് പുതിയ നമ്പർ നീക്കിവയ്ക്കും.",
  "FROM ACTION": "നടപടിയിൽ നിന്ന്",
  "REPORTING & APPROVALS": "റിപ്പോർട്ടിംഗും അംഗീകാരങ്ങളും",
  "The work location is taken from the Company Code's address.": "ജോലി സ്ഥലം കമ്പനി കോഡിന്റെ വിലാസത്തിൽ നിന്ന് എടുക്കുന്നു.",
  "(the head of their org unit)": "(അവരുടെ സ്ഥാപന യൂണിറ്റിന്റെ തലവൻ)",
  "(until {date})": "({date} വരെ)",
  "Face ID": "Face ID",
  "Face ID is not required for clock-in at the moment. Nothing to do.": "ഇപ്പോൾ ക്ലോക്ക്-ഇന്നിന് Face ID ആവശ്യമില്ല. ഒന്നും ചെയ്യേണ്ടതില്ല.",
  "has been hired. A welcome email with the login details has been sent.": "ജോലിയിൽ എടുത്തു. ലോഗിൻ വിവരങ്ങളോടു കൂടിയ ഒരു സ്വാഗത ഇമെയിൽ അയച്ചിട്ടുണ്ട്.",
  "hired": "ജോലിയിൽ എടുത്തു",
  "in the Employee Directory.": "ജീവനക്കാരുടെ ഡയറക്ടറിയിൽ.",
  "Next step for you:": "നിങ്ങളുടെ അടുത്ത ഘട്ടം:",
  "No reporting manager could be found for {name}, so leave and other requests have nobody to go to until one is assigned.": "{name}-ന് റിപ്പോർട്ടിംഗ് മാനേജരെ കണ്ടെത്താനായില്ല, അതിനാൽ ഒരാളെ നിയോഗിക്കുന്നതുവരെ ലീവ്, മറ്റ് അപേക്ഷകൾ പോകാൻ ആരുമില്ല.",
