  "Deactivated positions keep their full placement history and stay visible in the tree, tagged": "നിർജീവമാക്കിയ തസ്തികകൾ അവയുടെ പൂർണ്ണ നിയമന ചരിത്രം നിലനിർത്തുകയും ട്രീയിൽ ടാഗ് സഹിതം കാണപ്പെടുകയും ചെയ്യും:",
  "end their placement or vacate the seat — the position will just show as": "അവരുടെ നിയമനം അവസാനിപ്പിക്കുകയോ തസ്തിക ഒഴിവാക്കുകയോ ചെയ്യുന്നില്ല — തസ്തിക ഇങ്ങനെ കാണിക്കും:",
  "Failed to deactivate this position.": "ഈ തസ്തിക നിർജീവമാക്കാനായില്ല.",
  "not": "ചെയ്യുന്നില്ല",
  "position for {unit}. Deactivating it leaves the unit without a visible head until another position is marked chief.": "{unit}-ന്റെ തസ്തിക. ഇത് നിർജീവമാക്കിയാൽ മറ്റൊരു തസ്തിക മേധാവിയായി അടയാളപ്പെടുത്തുന്നതുവരെ യൂണിറ്റിന് ദൃശ്യമായ തലവൻ ഉണ്ടാകില്ല.",
  "This is the": "ഇതാണ്",
  "This position currently has an active holder,": "ഈ തസ്തികയ്ക്ക് നിലവിൽ ഒരു സജീവ ഉടമയുണ്ട്,",
  "{name} stays the holder through this date. The seat becomes vacant the day after.": "ഈ തീയതി വരെ {name} ഉടമയായി തുടരും. അടുത്ത ദിവസം തസ്തിക ഒഴിവാകും.",
  "Can't be before {date}, when this placement started.": "ഈ നിയമനം ആരംഭിച്ച {date}-ന് മുമ്പായിരിക്കരുത്.",
