  "No job templates yet.": "ഇതുവരെ ജോലി ടെംപ്ലേറ്റുകളില്ല.",
  "Reusable job titles offered when adding a position. Deactivate a template to stop offering it for new positions without losing history on positions that already use it.": "തസ്തിക ചേർക്കുമ്പോൾ നൽകുന്ന വീണ്ടും ഉപയോഗിക്കാവുന്ന ജോലി പേരുകൾ. ഇതിനകം ഉപയോഗിക്കുന്ന തസ്തികകളുടെ ചരിത്രം നഷ്ടപ്പെടാതെ പുതിയ തസ്തികകൾക്ക് നൽകുന്നത് നിർത്താൻ ഒരു ടെംപ്ലേറ്റ് നിർജീവമാക്കുക.",
