  "Permanently delete \"{name}\"? This can't be undone, and only works if it has never had a holder — if it has any placement history, this will be rejected; deactivate it instead.": "“{name}” സ്ഥിരമായി ഇല്ലാതാക്കണോ? ഇത് പഴയപടിയാക്കാനാകില്ല, ഒരിക്കലും ഉടമ ഉണ്ടായിട്ടില്ലെങ്കിൽ മാത്രമേ പ്രവർത്തിക്കൂ — ഏതെങ്കിലും നിയമന ചരിത്രമുണ്ടെങ്കിൽ ഇത് നിരസിക്കപ്പെടും; പകരം നിർജീവമാക്കുക.",
  "Permanently delete \"{name}\"? This can't be undone, and only works if none of its positions have ever been held by anyone — if any have, this will be rejected; deactivate the unit instead.": "“{name}” സ്ഥിരമായി ഇല്ലാതാക്കണോ? ഇത് പഴയപടിയാക്കാനാകില്ല, അതിലെ ഒരു തസ്തികയും ഒരിക്കലും ആരും വഹിച്ചിട്ടില്ലെങ്കിൽ മാത്രമേ പ്രവർത്തിക്കൂ — ഉണ്ടെങ്കിൽ ഇത് നിരസിക്കപ്പെടും; പകരം യൂണിറ്റ് നിർജീവമാക്കുക.",
