  "Has positions, but none is marked as chief": "പൊസിഷനുകളുണ്ട്, എന്നാൽ ഒന്നും ചീഫ് ആയി അടയാളപ്പെടുത്തിയിട്ടില്ല",
  "Most open seats": "ഏറ്റവും കൂടുതൽ ഒഴിഞ്ഞ സീറ്റുകൾ",
  "No positions and no sub-units": "പൊസിഷനുകളോ ഉപ-യൂണിറ്റുകളോ ഇല്ല",
  "Overview": "അവലോകനം",
  "Select a unit, position or person to see its details, or start with one of these.": "വിശദാംശങ്ങൾ കാണാൻ ഒരു യൂണിറ്റോ പൊസിഷനോ വ്യക്തിയോ തിരഞ്ഞെടുക്കുക, അല്ലെങ്കിൽ ഇവയിലൊന്നിൽ നിന്ന് തുടങ്ങുക.",
  "The unit's chief position has nobody in it": "യൂണിറ്റിന്റെ ചീഫ് പൊസിഷനിൽ ആരുമില്ല",
