  "{count} without a reporting line": "റിപ്പോർട്ടിംഗ് ലൈൻ ഇല്ലാത്ത {count} എണ്ണം",
  "Find position, person or unit": "പൊസിഷൻ, വ്യക്തി അല്ലെങ്കിൽ യൂണിറ്റ് കണ്ടെത്തുക",
  "Hide reports": "റിപ്പോർട്ടുകൾ മറയ്ക്കുക",
  "No positions yet.": "ഇതുവരെ പൊസിഷനുകളൊന്നുമില്ല.",
  "Positions with nobody reporting to them and no one they report to. Set 'Reports to' on a position to place it in the chain.": "തങ്ങൾക്ക് റിപ്പോർട്ട് ചെയ്യുന്നവരോ തങ്ങൾ റിപ്പോർട്ട് ചെയ്യുന്നവരോ ഇല്ലാത്ത പൊസിഷനുകൾ. ശൃംഖലയിൽ ചേർക്കാൻ പൊസിഷനിൽ ‘റിപ്പോർട്ട് ചെയ്യേണ്ടത്’ സജ്ജമാക്കുക.",
  "Show {count} direct report": "{count} നേരിട്ടുള്ള റിപ്പോർട്ട് കാണിക്കുക",
  "Show {count} direct reports": "{count} നേരിട്ടുള്ള റിപ്പോർട്ടുകൾ കാണിക്കുക",
  "Show reports": "റിപ്പോർട്ടുകൾ കാണിക്കുക",
  ", not a person. You mark one position in each unit as": ", വ്യക്തിയല്ല. ഓരോ യൂണിറ്റിലും ഒരു പൊസിഷൻ നിങ്ങൾ ഇങ്ങനെ അടയാളപ്പെടുത്തുന്നു:",
  "; whoever holds it is the head. The seat can stay": "; അത് വഹിക്കുന്നയാളാണ് തലവൻ. ആ സീറ്റ് ഇങ്ങനെ തുടരാം:",
  ". Access belongs to that seat—not the reporting chain; employees sharing a seat share its permissions. Use separate positions when employees need different access.": ". ആക്സസ് ആ സീറ്റിനുള്ളതാണ്—റിപ്പോർട്ടിംഗ് ശൃംഖലയ്ക്കല്ല; ഒരേ സീറ്റ് പങ്കിടുന്ന ജീവനക്കാർ അതിന്റെ അനുമതികളും പങ്കിടുന്നു. ജീവനക്കാർക്ക് വ്യത്യസ്ത ആക്സസ് ആവശ്യമെങ്കിൽ പ്രത്യേക പൊസിഷനുകൾ ഉപയോഗിക്കുക.",
