  "Org units, the positions inside them, and who holds each seat. Modeled on positions, so structure exists before anyone is hired.": "ഓർഗ് യൂണിറ്റുകൾ, അവയ്ക്കുള്ളിലെ പൊസിഷനുകൾ, ഓരോ സീറ്റും വഹിക്കുന്നവർ. പൊസിഷനുകളെ അടിസ്ഥാനമാക്കിയതിനാൽ ആരെയും നിയമിക്കുന്നതിന് മുമ്പുതന്നെ ഘടന നിലവിലുണ്ടാകും.",
