  "until you hire, so you never have to invent an employee just to create a unit.": "നിയമിക്കുന്നതുവരെ, അതിനാൽ ഒരു യൂണിറ്റ് സൃഷ്ടിക്കാൻ മാത്രമായി ഒരു ജീവനക്കാരനെ സൃഷ്ടിക്കേണ്ടതില്ല.",
