  "Loading position permissions…": "പൊസിഷൻ അനുമതികൾ ലോഡ് ചെയ്യുന്നു…",
  "Marks this position as a team manager for manager-based workflows.": "മാനേജർ അടിസ്ഥാനമാക്കിയുള്ള വർക്ക്ഫ്ലോകൾക്കായി ഈ പൊസിഷനെ ടീം മാനേജരായി അടയാളപ്പെടുത്തുന്നു.",
  "Module permissions": "മൊഡ്യൂൾ അനുമതികൾ",
  "No permissions match that search.": "ആ തിരയലിനോട് യോജിക്കുന്ന അനുമതികളൊന്നുമില്ല.",
