  "Select only the actions required for this position.": "ഈ പൊസിഷന് ആവശ്യമായ പ്രവർത്തനങ്ങൾ മാത്രം തിരഞ്ഞെടുക്കുക.",
  "Team manager": "ടീം മാനേജർ",
  "These permissions belong to this position. The current holder receives them; a future holder receives the same access. Permissions do not automatically pass between a manager and their reports. Give each position its own access below.": "ഈ അനുമതികൾ ഈ പൊസിഷന്റേതാണ്. നിലവിലെ ആൾക്ക് അവ ലഭിക്കുന്നു; ഭാവിയിൽ വരുന്നയാൾക്കും അതേ ആക്സസ് ലഭിക്കും. അനുമതികൾ ഒരു മാനേജർക്കും അദ്ദേഹത്തിന്റെ കീഴിലുള്ളവർക്കും ഇടയിൽ സ്വയം കൈമാറപ്പെടില്ല. ഓരോ പൊസിഷനും താഴെ അതിന്റേതായ ആക്സസ് നൽകുക.",
  "Turning on Team manager also checked the usual manager permissions below (View employees, Approve leave, View attendance) so this position isn't left with 0 permissions. Uncheck any you don't want before saving.": "ടീം മാനേജർ ഓണാക്കിയപ്പോൾ ഈ പൊസിഷനിൽ അനുമതികളൊന്നും ഇല്ലാതാകാതിരിക്കാൻ സാധാരണ മാനേജർ അനുമതികളും (ജീവനക്കാരെ കാണുക, ലീവ് അംഗീകരിക്കുക, ഹാജർ കാണുക) താഴെ തിരഞ്ഞെടുത്തിട്ടുണ്ട്. സേവ് ചെയ്യുന്നതിന് മുമ്പ് ആവശ്യമില്ലാത്തവ ഒഴിവാക്കുക.",
  "Unit head": "യൂണിറ്റ് തലവൻ",
