  "— not done here.": "— ഇവിടെ ചെയ്യുന്നില്ല.",
  "All {count} manager(s) have approved.": "എല്ലാ {count} മാനേജർമാരും അംഗീകരിച്ചു.",
  "All approvals complete. You can now proceed to compute payroll.": "എല്ലാ അംഗീകാരങ്ങളും പൂർത്തിയായി. ഇനി പേറോൾ കണക്കാക്കാൻ തുടരാം.",
  "Approval happens on the Team Approvals page, not here — go to": "അംഗീകാരം ഇവിടെയല്ല, ടീം അംഗീകാരങ്ങൾ പേജിലാണ് നടക്കുന്നത് — ഇവിടേക്ക് പോകുക:",
  "Approved by": "അംഗീകരിച്ചത്",
