  "Each manager must sign off on their team's attendance": "ഓരോ മാനേജരും തങ്ങളുടെ ടീമിന്റെ ഹാജർ അംഗീകരിക്കണം",
  "HR Approval (L2)": "എച്ച്ആർ അംഗീകാരം (L2)",
  "HR Ops → Approvals → Attendance Approval": "എച്ച്ആർ പ്രവർത്തനങ്ങൾ → അംഗീകാരങ്ങൾ → ഹാജർ അംഗീകാരം",
  "HR sign-off is the final step before payroll can be processed.": "പേറോൾ പ്രോസസ് ചെയ്യുന്നതിന് മുമ്പുള്ള അവസാന ഘട്ടമാണ് എച്ച്ആർ അംഗീകാരം.",
  "HR verifies and signs off — unlocks payroll processing": "എച്ച്ആർ പരിശോധിച്ച് അംഗീകരിക്കുന്നു — പേറോൾ പ്രോസസിംഗ് തുറക്കുന്നു",
