  "No managers with team management rights are configured — HR can approve directly.": "ടീം മാനേജ്മെന്റ് അവകാശമുള്ള മാനേജർമാരെ സജ്ജമാക്കിയിട്ടില്ല — എച്ച്ആറിന് നേരിട്ട് അംഗീകരിക്കാം.",
  "on {date}": "{date}-ന്",
  "Refresh status": "നില റിഫ്രഷ് ചെയ്യുക",
  "to sign off.": "അംഗീകരിക്കാൻ.",
  "Waiting for all managers (L1) to approve first": "ആദ്യം എല്ലാ മാനേജർമാരും (L1) അംഗീകരിക്കുന്നതിനായി കാത്തിരിക്കുന്നു",
  "Waiting for HR to sign off from": "എച്ച്ആർ ഇവിടെ നിന്ന് അംഗീകരിക്കുന്നതിനായി കാത്തിരിക്കുന്നു:",
  "Waiting for HR/Admin to complete the L1 step directly — no managers are configured for this cycle.": "എച്ച്ആർ/അഡ്മിൻ L1 ഘട്ടം നേരിട്ട് പൂർത്തിയാക്കുന്നതിനായി കാത്തിരിക്കുന്നു — ഈ സൈക്കിളിൽ മാനേജർമാരെ സജ്ജമാക്കിയിട്ടില്ല.",
  "Waiting for other managers to approve. Refresh to check latest status.": "മറ്റ് മാനേജർമാർ അംഗീകരിക്കുന്നതിനായി കാത്തിരിക്കുന്നു. ഏറ്റവും പുതിയ നില അറിയാൻ റിഫ്രഷ് ചെയ്യുക.",
  "Your sign-off is required — approve it from": "നിങ്ങളുടെ അംഗീകാരം ആവശ്യമാണ് — ഇവിടെ നിന്ന് അംഗീകരിക്കുക:",
  "{amount} total": "ആകെ {amount}",
  "All salaries marked as paid. Payroll run for this cycle is complete.": "എല്ലാ ശമ്പളവും നൽകിയതായി അടയാളപ്പെടുത്തി. ഈ സൈക്കിളിലെ പേറോൾ റൺ പൂർത്തിയായി.",
  "Checking salary transfer readiness…": "ശമ്പള കൈമാറ്റത്തിനുള്ള സജ്ജത പരിശോധിക്കുന്നു…",
  "Confirm and Lock": "സ്ഥിരീകരിച്ച് ലോക്ക് ചെയ്യുക",
  "Confirm Salary Transfer": "ശമ്പള കൈമാറ്റം സ്ഥിരീകരിക്കുക",
  "Confirm salary transfer?": "ശമ്പള കൈമാറ്റം സ്ഥിരീകരിക്കണോ?",
  "Download NEFT CSV": "NEFT CSV ഡൗൺലോഡ് ചെയ്യുക",
  "Employees have acknowledged their payslips. Confirm the salary transfer to lock bank details and generate the NEFT CSV.": "ജീവനക്കാർ അവരുടെ ശമ്പള സ്ലിപ്പുകൾ സ്വീകരിച്ചു. ബാങ്ക് വിവരങ്ങൾ ലോക്ക് ചെയ്യാനും NEFT CSV തയ്യാറാക്കാനും ശമ്പള കൈമാറ്റം സ്ഥിരീകരിക്കുക.",
  "Failed to confirm the salary transfer.": "ശമ്പള കൈമാറ്റം സ്ഥിരീകരിക്കാനായില്ല.",
  "Failed to download the bank transfer file.": "ബാങ്ക് കൈമാറ്റ ഫയൽ ഡൗൺലോഡ് ചെയ്യാനായില്ല.",
  "Failed to mark as paid.": "നൽകിയതായി അടയാളപ്പെടുത്താനായില്ല.",
  "Finish Payroll Run": "പേറോൾ റൺ പൂർത്തിയാക്കുക",
  "Gross − all deductions": "ആകെ വരുമാനം − എല്ലാ കിഴിവുകളും",
  "In this payroll run": "ഈ പേറോൾ റണ്ണിൽ",
  "Locking Transfer…": "കൈമാറ്റം ലോക്ക് ചെയ്യുന്നു…",
  "Mark All Paid": "എല്ലാം നൽകിയതായി അടയാളപ്പെടുത്തുക",
  "Mark Payroll as Paid": "പേറോൾ നൽകിയതായി അടയാളപ്പെടുത്തുക",
  "Mark payroll as paid?": "പേറോൾ നൽകിയതായി അടയാളപ്പെടുത്തണോ?",
  "Marking Paid…": "നൽകിയതായി അടയാളപ്പെടുത്തുന്നു…",
  "Net Salary": "അറ്റ ശമ്പളം",
  "Paid": "നൽകി",
  "Preparing CSV…": "CSV തയ്യാറാക്കുന്നു…",
  "Salary transfer locked for {count} employee(s). Download the NEFT CSV and submit it to your bank before marking payroll paid.": "{count} ജീവനക്കാർക്കുള്ള ശമ്പള കൈമാറ്റം ലോക്ക് ചെയ്തു. പേറോൾ നൽകിയതായി അടയാളപ്പെടുത്തുന്നതിന് മുമ്പ് NEFT CSV ഡൗൺലോഡ് ചെയ്ത് ബാങ്കിൽ സമർപ്പിക്കുക.",
  "Salary transfer readiness is unavailable.": "ശമ്പള കൈമാറ്റ സജ്ജത ലഭ്യമല്ല.",
  "This locks the current bank details and net pay for all {count} employee(s) into a transfer batch. Download the NEFT CSV after confirmation and submit it through your bank before marking payroll paid.": "ഇത് എല്ലാ {count} ജീവനക്കാരുടെയും നിലവിലെ ബാങ്ക് വിവരങ്ങളും അറ്റ ശമ്പളവും ഒരു കൈമാറ്റ ബാച്ചിലേക്ക് ലോക്ക് ചെയ്യും. സ്ഥിരീകരണത്തിന് ശേഷം NEFT CSV ഡൗൺലോഡ് ചെയ്ത്, പേറോൾ നൽകിയതായി അടയാളപ്പെടുത്തുന്നതിന് മുമ്പ് നിങ്ങളുടെ ബാങ്ക് വഴി സമർപ്പിക്കുക.",
  "This marks all {count} payslip (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "ഇത് എല്ലാ {count} ശമ്പള സ്ലിപ്പും (ആകെ {amount}) നൽകിയതായി അടയാളപ്പെടുത്തുകയും ഈ പേറോൾ റൺ അവസാനിപ്പിക്കുകയും ചെയ്യും. ഇത് പണം കൈമാറുന്നില്ല — കൈമാറ്റം നേരത്തേ നടന്നു എന്ന് രേഖപ്പെടുത്തുക മാത്രമാണ് ചെയ്യുന്നത്. ഇത് പഴയപടിയാക്കാൻ കഴിയില്ല.",
  "This marks all {count} payslips (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "ഇത് എല്ലാ {count} ശമ്പള സ്ലിപ്പുകളും (ആകെ {amount}) നൽകിയതായി അടയാളപ്പെടുത്തുകയും ഈ പേറോൾ റൺ അവസാനിപ്പിക്കുകയും ചെയ്യും. ഇത് പണം കൈമാറുന്നില്ല — കൈമാറ്റം നേരത്തേ നടന്നു എന്ന് രേഖപ്പെടുത്തുക മാത്രമാണ് ചെയ്യുന്നത്. ഇത് പഴയപടിയാക്കാൻ കഴിയില്ല.",
  "Total Net Payable": "ആകെ നൽകേണ്ട അറ്റ തുക",
