  "Net Pay Payable": "നൽകേണ്ട അറ്റ ശമ്പളം",
  "No payslips found. Employees may be missing CTC or salary structure.": "ശമ്പള സ്ലിപ്പുകളൊന്നും കണ്ടെത്തിയില്ല. ജീവനക്കാർക്ക് CTC യോ ശമ്പള ഘടനയോ ഇല്ലാത്തതാകാം.",
