  "Set up their salary in Employees → Salary tab, then reprocess to include them.": "ജീവനക്കാർ → ശമ്പളം ടാബിൽ അവരുടെ ശമ്പളം സജ്ജമാക്കുക, തുടർന്ന് അവരെ ഉൾപ്പെടുത്താൻ വീണ്ടും പ്രോസസ് ചെയ്യുക.",
  "Spl. Allow.": "സ്പെഷ്യൽ അലവൻസ്",
  "Statutory Deductions": "നിയമപരമായ കിഴിവുകൾ",
  "This recalculates salaries for all {count} employee in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "ഇത് ഈ സൈക്കിളിലെ എല്ലാ {count} ജീവനക്കാരന്റെയും ശമ്പളം തുടക്കം മുതൽ വീണ്ടും കണക്കാക്കുകയും നിലവിലെ കണക്കുകൾ മാറ്റിയെഴുതുകയും ചെയ്യും — ഈ ശമ്പള സ്ലിപ്പുകളിൽ ഇതിനകം വരുത്തിയ ബോണസ്, റീഇംബേഴ്സ്മെന്റ് ക്രമീകരണങ്ങൾ ഉൾപ്പെടെ. ഇത് പഴയപടിയാക്കാൻ കഴിയില്ല.",
  "This recalculates salaries for all {count} employees in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "ഇത് ഈ സൈക്കിളിലെ എല്ലാ {count} ജീവനക്കാരുടെയും ശമ്പളം തുടക്കം മുതൽ വീണ്ടും കണക്കാക്കുകയും നിലവിലെ കണക്കുകൾ മാറ്റിയെഴുതുകയും ചെയ്യും — ഈ ശമ്പള സ്ലിപ്പുകളിൽ ഇതിനകം വരുത്തിയ ബോണസ്, റീഇംബേഴ്സ്മെന്റ് ക്രമീകരണങ്ങൾ ഉൾപ്പെടെ. ഇത് പഴയപടിയാക്കാൻ കഴിയില്ല.",
  "This will calculate salaries for all eligible employees using their CTC, salary structure, and statutory rules for each branch.": "ഇത് അർഹരായ എല്ലാ ജീവനക്കാരുടെയും ശമ്പളം അവരുടെ CTC, ശമ്പള ഘടന, ഓരോ ബ്രാഞ്ചിലെയും നിയമപരമായ ചട്ടങ്ങൾ എന്നിവ ഉപയോഗിച്ച് കണക്കാക്കും.",
  "{count} adjustment(s) imported.": "{count} ക്രമീകരണങ്ങൾ ഇംപോർട്ട് ചെയ്തു.",
