  "No payroll cycles yet. Run your first payroll to enable ECR export.": "ഇതുവരെ പേറോൾ സൈക്കിളുകളില്ല. ECR എക്സ്പോർട്ട് പ്രവർത്തനക്ഷമമാക്കാൻ ആദ്യ പേറോൾ റൺ ചെയ്യുക.",
