  "Select a period to export.": "എക്സ്പോർട്ട് ചെയ്യാൻ ഒരു കാലയളവ് തിരഞ്ഞെടുക്കുക.",
  "text file": "ടെക്സ്റ്റ് ഫയൽ",
  "{count} employees · Net:": "{count} ജീവനക്കാർ · അറ്റം:",
  "All payslips dispatched. Employees have the configured window to raise queries.": "എല്ലാ ശമ്പള സ്ലിപ്പുകളും അയച്ചു. സംശയങ്ങൾ ഉന്നയിക്കാൻ ജീവനക്കാർക്ക് നിശ്ചയിച്ച കാലയളവുണ്ട്.",
  "All payslips dispatched. Employees have until {date} to raise queries.": "എല്ലാ ശമ്പള സ്ലിപ്പുകളും അയച്ചു. സംശയങ്ങൾ ഉന്നയിക്കാൻ ജീവനക്കാർക്ക് {date} വരെ സമയമുണ്ട്.",
  "Continue to Mark as Paid": "നൽകിയതായി അടയാളപ്പെടുത്താൻ തുടരുക",
  "Dispatch All": "എല്ലാം അയയ്ക്കുക",
  "Dispatch Payslips": "ശമ്പള സ്ലിപ്പുകൾ അയയ്ക്കുക",
