  "Dispatched": "അയച്ചു",
  "Dispatching…": "അയയ്ക്കുന്നു…",
  "Failed to dispatch payslips.": "ശമ്പള സ്ലിപ്പുകൾ അയയ്ക്കാനായില്ല.",
  "No payslips found for this cycle.": "ഈ സൈക്കിളിന് ശമ്പള സ്ലിപ്പുകളൊന്നും കണ്ടെത്തിയില്ല.",
  "This will email payslips to all {count} employee in this cycle (total net pay {amount}). Employees will be able to view and query them immediately. This cannot be undone.": "ഇത് ഈ സൈക്കിളിലെ എല്ലാ {count} ജീവനക്കാരന്റെയും ശമ്പള സ്ലിപ്പ് ഇമെയിൽ ചെയ്യും (ആകെ അറ്റ ശമ്പളം {amount}). ജീവനക്കാർക്ക് ഉടൻ തന്നെ അവ കാണാനും സംശയങ്ങൾ ഉന്നയിക്കാനും കഴിയും. ഇത് പഴയപടിയാക്കാൻ കഴിയില്ല.",
  "This will email payslips to all {count} employees in this cycle (total net pay {amount}). Employees will be able to view and query them immediately. This cannot be undone.": "ഇത് ഈ സൈക്കിളിലെ എല്ലാ {count} ജീവനക്കാരുടെയും ശമ്പള സ്ലിപ്പുകൾ ഇമെയിൽ ചെയ്യും (ആകെ അറ്റ ശമ്പളം {amount}). ജീവനക്കാർക്ക് ഉടൻ തന്നെ അവ കാണാനും സംശയങ്ങൾ ഉന്നയിക്കാനും കഴിയും. ഇത് പഴയപടിയാക്കാൻ കഴിയില്ല.",
  "Total ({count} employees)": "ആകെ ({count} ജീവനക്കാർ)",
  "Action Required — {count} Pending Cycle": "നടപടി ആവശ്യമാണ് — തീർപ്പാക്കാനുള്ള {count} സൈക്കിൾ",
