  "Ready": "തയ്യാർ",
  "{count} critical error(s)": "{count} ഗുരുതര പിശകുകൾ",
  "{count} employee(s) earning above ₹21,000 have no deductions. Ensure statutory config is set for their branch.": "₹21,000-ൽ കൂടുതൽ വരുമാനമുള്ള {count} ജീവനക്കാർക്ക് കിഴിവുകളില്ല. അവരുടെ ബ്രാഞ്ചിന് നിയമപരമായ സജ്ജീകരണം ചെയ്തിട്ടുണ്ടെന്ന് ഉറപ്പാക്കുക.",
  "{count} employee(s) have more than 15 LOP days. Verify this is correct before proceeding.": "{count} ജീവനക്കാർക്ക് 15-ൽ കൂടുതൽ LOP ദിവസങ്ങളുണ്ട്. തുടരുന്നതിന് മുമ്പ് ഇത് ശരിയാണെന്ന് ഉറപ്പാക്കുക.",
  "{count} employee(s) have negative net pay. Deductions exceed gross earnings — review LOP or advance recovery entries.": "{count} ജീവനക്കാർക്ക് അറ്റ ശമ്പളം നെഗറ്റീവ് ആണ്. കിഴിവുകൾ ആകെ വരുമാനത്തേക്കാൾ കൂടുതലാണ് — LOP അല്ലെങ്കിൽ അഡ്വാൻസ് തിരിച്ചുപിടിക്കൽ എൻട്രികൾ പരിശോധിക്കുക.",
  "{count} employee(s) have zero gross earnings. Check that their CTC and salary structure are configured correctly.": "{count} ജീവനക്കാർക്ക് ആകെ വരുമാനം പൂജ്യമാണ്. അവരുടെ CTC യും ശമ്പള ഘടനയും ശരിയായി സജ്ജമാക്കിയിട്ടുണ്ടോ എന്ന് പരിശോധിക്കുക.",
  "{count} Error": "{count} പിശക്",
  "{count} Errors": "{count} പിശകുകൾ",
  "{count} Warning": "{count} മുന്നറിയിപ്പ്",
  "{count} Warnings": "{count} മുന്നറിയിപ്പുകൾ",
  "All Clear": "എല്ലാം ശരിയാണ്",
  "All validation checks passed or acknowledged. Ready to generate payslips.": "എല്ലാ പരിശോധനകളും വിജയിച്ചു അല്ലെങ്കിൽ അംഗീകരിച്ചു. ശമ്പള സ്ലിപ്പുകൾ തയ്യാറാക്കാൻ ഒരുങ്ങിയിരിക്കുന്നു.",
  "High Loss of Pay (>15 days)": "ഉയർന്ന ശമ്പളനഷ്ടം (>15 ദിവസം)",
  "Ignore": "അവഗണിക്കുക",
  "Ignored": "അവഗണിച്ചത്",
  "must be resolved or explicitly ignored before proceeding.": "തുടരുന്നതിന് മുമ്പ് പരിഹരിക്കുകയോ വ്യക്തമായി അവഗണിക്കുകയോ ചെയ്യണം.",
  "Negative Net Pay": "നെഗറ്റീവ് അറ്റ ശമ്പളം",
  "No critical errors. You may continue with {count} unresolved warning(s).": "ഗുരുതര പിശകുകളില്ല. പരിഹരിക്കാത്ത {count} മുന്നറിയിപ്പുകളോടെ തുടരാം.",
  "No issues detected. All {count} payslips look correct.": "പ്രശ്നങ്ങളൊന്നും കണ്ടെത്തിയില്ല. എല്ലാ {count} ശമ്പള സ്ലിപ്പുകളും ശരിയാണെന്ന് തോന്നുന്നു.",
  "No Payslips Generated": "ശമ്പള സ്ലിപ്പുകളൊന്നും തയ്യാറാക്കിയിട്ടില്ല",
  "No payslips were generated. Click Back → Back → Earn & Deduct → \"Compute Salaries\" to reprocess after ensuring all employees have CTC configured.": "ശമ്പള സ്ലിപ്പുകളൊന്നും തയ്യാറാക്കിയില്ല. എല്ലാ ജീവനക്കാർക്കും CTC സജ്ജമാക്കിയെന്ന് ഉറപ്പാക്കിയ ശേഷം വീണ്ടും പ്രോസസ് ചെയ്യാൻ തിരികെ → തിരികെ → വരുമാനവും കിഴിവും → “ശമ്പളം കണക്കാക്കുക” ക്ലിക്ക് ചെയ്യുക.",
  "No Statutory Deductions Applied": "നിയമപരമായ കിഴിവുകളൊന്നും ബാധകമാക്കിയിട്ടില്ല",
  "Reviewed": "അവലോകനം ചെയ്തു",
