  "Reports appear here when your role gives you access to the data they cover.": "റിപ്പോർട്ടുകൾ ഉൾക്കൊള്ളുന്ന ഡാറ്റയിലേക്ക് നിങ്ങളുടെ റോൾ ആക്സസ് നൽകുമ്പോൾ അവ ഇവിടെ കാണാം.",
  "Comment": "അഭിപ്രായം",
  "This request will be rejected and the workflow will stop here.": "ഈ അപേക്ഷ നിരസിക്കുകയും വർക്ക്ഫ്ലോ ഇവിടെ അവസാനിക്കുകയും ചെയ്യും.",
  "Leave blank to file for yourself, or search an employee…": "നിങ്ങൾക്കായി നൽകാൻ ഒഴിച്ചിടുക, അല്ലെങ്കിൽ ഒരു ജീവനക്കാരനെ തിരയുക…",
  "{count} day from request date": "അപേക്ഷ തീയതി മുതൽ {count} ദിവസം",
  "{count} days from request date": "അപേക്ഷ തീയതി മുതൽ {count} ദിവസങ്ങൾ",
  "A document is already attached. Choosing a new file replaces it.": "ഒരു ഡോക്യുമെന്റ് ഇതിനകം ഘടിപ്പിച്ചിട്ടുണ്ട്. പുതിയ ഫയൽ തിരഞ്ഞെടുത്താൽ അത് മാറ്റിസ്ഥാപിക്കും.",
  "Cannot be earlier than the request date.": "അപേക്ഷ തീയതിക്ക് മുമ്പായിരിക്കരുത്.",
  "Choose file…": "ഫയൽ തിരഞ്ഞെടുക്കുക…",
  "e.g. Family relocation to another country": "ഉദാ. കുടുംബം മറ്റൊരു രാജ്യത്തേക്ക് താമസം മാറുന്നു",
  "Edit Separation Request": "വിടവാങ്ങൽ അപേക്ഷ എഡിറ്റ് ചെയ്യുക",
  "Enter a valid number of days.": "സാധുവായ ദിവസങ്ങളുടെ എണ്ണം നൽകുക.",
  "Failed to submit the separation request. Please try again.": "വിടവാങ്ങൽ അപേക്ഷ സമർപ്പിക്കാനായില്ല. ദയവായി വീണ്ടും ശ്രമിക്കുക.",
  "Leave blank to file this request for yourself.": "ഈ അപേക്ഷ നിങ്ങൾക്കായി നൽകാൻ ഒഴിച്ചിടുക.",
  "Notice Period (days)": "നോട്ടീസ് കാലയളവ് (ദിവസം)",
