  "View / Download Document": "ഡോക്യുമെന്റ് കാണുക / ഡൗൺലോഡ് ചെയ്യുക",
  "{count} earned leave day(s)": "{count} എർൺഡ് ലീവ് ദിവസങ്ങൾ",
  "{served} of {required} days served ({short} short). A recovery of {amount} has been calculated. Confirm with HR or finance whether this recovery applies before finalising.": "{required} ദിവസത്തിൽ {served} ദിവസം പൂർത്തിയാക്കി ({short} കുറവ്). {amount} തിരിച്ചുപിടിക്കൽ കണക്കാക്കിയിട്ടുണ്ട്. അന്തിമമാക്കുന്നതിന് മുമ്പ് ഈ തിരിച്ചുപിടിക്കൽ ബാധകമാണോ എന്ന് എച്ച്ആറിനോടോ ഫിനാൻസിനോടോ ഉറപ്പാക്കുക.",
  "{served}/{required} days served — {short} day shortfall": "{served}/{required} ദിവസം പൂർത്തിയാക്കി — {short} ദിവസത്തിന്റെ കുറവ്",
  "Deductions exceed earnings — this amount is owed back by the employee, not paid to them.": "കിഴിവുകൾ വരുമാനത്തേക്കാൾ കൂടുതലാണ് — ഈ തുക ജീവനക്കാരൻ തിരികെ നൽകേണ്ടതാണ്, അവർക്ക് നൽകുന്നതല്ല.",
  "Failed to finalize the settlement.": "സെറ്റിൽമെന്റ് അന്തിമമാക്കാനായില്ല.",
  "Failed to update the settlement.": "സെറ്റിൽമെന്റ് അപ്ഡേറ്റ് ചെയ്യാനായില്ല.",
  "Finalize": "അന്തിമമാക്കുക",
