  "Finalized by {name}": "{name} അന്തിമമാക്കി",
  "Finalizing…": "അന്തിമമാക്കുന്നു…",
  "Full {required}-day notice served": "മുഴുവൻ {required} ദിവസത്തെ നോട്ടീസ് പൂർത്തിയാക്കി",
  "Full & Final Settlement": "ഫുൾ & ഫൈനൽ സെറ്റിൽമെന്റ്",
  "Leave Encashment": "ലീവ് എൻക്യാഷ്മെന്റ്",
  "Net Recoverable from Employee": "ജീവനക്കാരനിൽ നിന്ന് തിരിച്ചുപിടിക്കേണ്ട അറ്റ തുക",
  "Notice Period Recovery": "നോട്ടീസ് കാലയളവ് തിരിച്ചുപിടിക്കൽ",
  "Notice period shortfall:": "നോട്ടീസ് കാലയളവിലെ കുറവ്:",
  "Other Adjustment (+/−)": "മറ്റ് ക്രമീകരണം (+/−)",
  "Other Adjustment Note": "മറ്റ് ക്രമീകരണ കുറിപ്പ്",
  "Other Adjustment: {amount}": "മറ്റ് ക്രമീകരണം: {amount}",
  "Pro-rata Salary": "അനുപാത ശമ്പളം",
  "Pro-rated salary, leave encashment, and notice-period shortfall are computed automatically (CTC ÷ 30, Earned Leave balance) — a starting estimate to review, not a final figure. Gratuity, bonus, reimbursements, advances, and TDS are always entered by hand.": "അനുപാത ശമ്പളം, ലീവ് എൻക്യാഷ്മെന്റ്, നോട്ടീസ് കാലയളവിലെ കുറവ് എന്നിവ സ്വയം കണക്കാക്കുന്നു (CTC ÷ 30, എർൺഡ് ലീവ് ബാലൻസ്) — പരിശോധിക്കാനുള്ള ഒരു പ്രാഥമിക കണക്കാണ്, അന്തിമ തുകയല്ല. ഗ്രാറ്റ്വിറ്റി, ബോണസ്, റീഇംബേഴ്സ്മെന്റുകൾ, അഡ്വാൻസുകൾ, TDS എന്നിവ എപ്പോഴും കൈകൊണ്ട് നൽകണം.",
  "Settlement finalized.": "സെറ്റിൽമെന്റ് അന്തിമമാക്കി.",
  "Settlement updated.": "സെറ്റിൽമെന്റ് അപ്ഡേറ്റ് ചെയ്തു.",
  "This is a recovery — the employee owes the company (net payable may be negative)": "ഇത് തിരിച്ചുപിടിക്കലാണ് — ജീവനക്കാരൻ കമ്പനിക്ക് നൽകാനുണ്ട് (നൽകേണ്ട അറ്റ തുക നെഗറ്റീവ് ആകാം)",
  "This locks the full & final settlement at a net payable of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "ഇത് ഫുൾ & ഫൈനൽ സെറ്റിൽമെന്റ് {amount} അറ്റ നൽകേണ്ട തുകയായി ലോക്ക് ചെയ്യും. അന്തിമമാക്കിയാൽ ഈ സെറ്റിൽമെന്റിലെ ഒരു ഫീൽഡും — ഗ്രാറ്റ്വിറ്റി, ബോണസ്, റീഇംബേഴ്സ്മെന്റുകൾ, അഡ്വാൻസുകൾ, TDS, ക്രമീകരണങ്ങൾ — വീണ്ടും എഡിറ്റ് ചെയ്യാൻ കഴിയില്ല. ഇത് പഴയപടിയാക്കാൻ കഴിയില്ല.",
  "This locks the full & final settlement at a net recoverable from the employee of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "ഇത് ഫുൾ & ഫൈനൽ സെറ്റിൽമെന്റ് ജീവനക്കാരനിൽ നിന്ന് തിരിച്ചുപിടിക്കേണ്ട അറ്റ തുക {amount} ആയി ലോക്ക് ചെയ്യും. അന്തിമമാക്കിയാൽ ഈ സെറ്റിൽമെന്റിലെ ഒരു ഫീൽഡും — ഗ്രാറ്റ്വിറ്റി, ബോണസ്, റീഇംബേഴ്സ്മെന്റുകൾ, അഡ്വാൻസുകൾ, TDS, ക്രമീകരണങ്ങൾ — വീണ്ടും എഡിറ്റ് ചെയ്യാൻ കഴിയില്ല. ഇത് പഴയപടിയാക്കാൻ കഴിയില്ല.",
