  "Could not save.": "സേവ് ചെയ്യാനായില്ല.",
  "Everyone": "എല്ലാവരും",
  "Everyone gets the baseline. On top of that, each person gets the access of the position they hold (set in": "എല്ലാവർക്കും അടിസ്ഥാന അനുമതികൾ ലഭിക്കും. അതിനു പുറമേ, ഓരോരുത്തർക്കും അവർ വഹിക്കുന്ന പൊസിഷന്റെ ആക്സസും ലഭിക്കും (ഇവിടെ സജ്ജമാക്കിയത്:",
