  "What every employee can do, whatever their position. Changes take effect the next time each person signs in.": "പൊസിഷൻ ഏതായാലും എല്ലാ ജീവനക്കാർക്കും ചെയ്യാൻ കഴിയുന്നത്. ഓരോരുത്തരും അടുത്ത തവണ സൈൻ ഇൻ ചെയ്യുമ്പോൾ മാറ്റങ്ങൾ പ്രാബല്യത്തിൽ വരും.",
  "You have read-only access to baseline permissions.": "അടിസ്ഥാന അനുമതികൾ കാണാൻ മാത്രമേ നിങ്ങൾക്ക് ആക്സസ് ഉള്ളൂ.",
