  "State-wise. One GSTIN per state. Each is checked against your PAN.": "സംസ്ഥാനം തിരിച്ച്. ഓരോ സംസ്ഥാനത്തിനും ഒരു GSTIN. ഓരോന്നും നിങ്ങളുടെ PAN-മായി ഒത്തുനോക്കുന്നു.",
