  "Every ID is 8 digits and purely numeric. Each worker type has its own range, so the first digit tells you the type. The ID is picked automatically at hire; changing someone's type later does not change their existing ID.": "ഓരോ ഐഡിയും 8 അക്കങ്ങളുള്ള പൂർണ്ണമായും സംഖ്യാരൂപത്തിലുള്ളതാണ്. ഓരോ തൊഴിലാളി തരത്തിനും സ്വന്തം ശ്രേണിയുണ്ട്, അതിനാൽ ആദ്യ അക്കം തരം സൂചിപ്പിക്കുന്നു. നിയമന സമയത്ത് ഐഡി സ്വയം തിരഞ്ഞെടുക്കും; പിന്നീട് ഒരാളുടെ തരം മാറ്റിയാലും അവരുടെ നിലവിലെ ഐഡി മാറില്ല.",
