  "Two worker types share some of the same numbers. Change a range so they no longer overlap before saving.": "രണ്ട് തൊഴിലാളി തരങ്ങൾ ചില നമ്പറുകൾ പങ്കിടുന്നു. സേവ് ചെയ്യുന്നതിന് മുമ്പ് ഒരു ശ്രേണി മാറ്റി അവ ഓവർലാപ്പ് ചെയ്യാതെ നോക്കുക.",
