  "This removes the custom PF configuration for {branch}. The branch will immediately fall back to system defaults ({employee}% employee / {employer}% employer on basic salary up to ₹{ceiling}) for any payroll processed after this. This cannot be undone.": "ഇത് {branch}-ന്റെ ഇഷ്ടാനുസൃത PF കോൺഫിഗറേഷൻ നീക്കം ചെയ്യും. ഇതിന് ശേഷം പ്രോസസ് ചെയ്യുന്ന ഏതൊരു പേറോളിനും ബ്രാഞ്ച് ഉടൻ തന്നെ സിസ്റ്റം ഡിഫോൾട്ടുകളിലേക്ക് മടങ്ങും (₹{ceiling} വരെയുള്ള അടിസ്ഥാന ശമ്പളത്തിൽ ജീവനക്കാരൻ {employee}% / തൊഴിലുടമ {employer}%). ഇത് തിരികെ മാറ്റാൻ കഴിയില്ല.",
  "Using system defaults": "സിസ്റ്റം ഡിഫോൾട്ടുകൾ ഉപയോഗിക്കുന്നു",
