  "Computed automatically from each employee's branch (50% of Basic if the branch is marked Metro, 40% otherwise) — the Percentage field below is ignored for this calculation type.": "ഓരോ ജീവനക്കാരന്റെയും ബ്രാഞ്ച് അനുസരിച്ച് സ്വയമേവ കണക്കാക്കുന്നു (ബ്രാഞ്ച് മെട്രോ ആണെങ്കിൽ അടിസ്ഥാന ശമ്പളത്തിന്റെ 50%, അല്ലെങ്കിൽ 40%) — ഈ കണക്കുകൂട്ടൽ തരത്തിന് താഴെയുള്ള ശതമാനം ഫീൽഡ് അവഗണിക്കും.",
  "Could not delete this salary structure. Please try again.": "ഈ ശമ്പള ഘടന ഇല്ലാതാക്കാനായില്ല. ദയവായി വീണ്ടും ശ്രമിക്കുക.",
  "Could not schedule this component change.": "ഈ ഘടക മാറ്റം ഷെഡ്യൂൾ ചെയ്യാനായില്ല.",
  "Create Salary Structure": "ശമ്പള ഘടന സൃഷ്ടിക്കുക",
  "Create Structure": "ഘടന സൃഷ്ടിക്കുക",
