  "Deactivate Salary Structure?": "ശമ്പള ഘടന നിർജീവമാക്കണോ?",
  "Default: next payroll cycle start ({date}).": "ഡിഫോൾട്ട്: അടുത്ത പേറോൾ സൈക്കിൾ ആരംഭം ({date}).",
  "Defaults to the next payroll cycle; issued payslips are not recalculated.": "അടുത്ത പേറോൾ സൈക്കിളിലേക്ക് ഡിഫോൾട്ടാകും; നൽകിയ ശമ്പള സ്ലിപ്പുകൾ വീണ്ടും കണക്കാക്കില്ല.",
  "Delete this salary structure": "ഈ ശമ്പള ഘടന ഇല്ലാതാക്കുക",
  "Disabling {name} affects {count} employee(s). Existing values and historical payslips are retained; the component will be excluded from future calculations from the selected date.": "{name} പ്രവർത്തനരഹിതമാക്കുന്നത് {count} ജീവനക്കാരെ ബാധിക്കും. നിലവിലെ മൂല്യങ്ങളും പഴയ ശമ്പള സ്ലിപ്പുകളും സൂക്ഷിക്കും; തിരഞ്ഞെടുത്ത തീയതി മുതൽ ഘടകം ഭാവി കണക്കുകൂട്ടലുകളിൽ നിന്ന് ഒഴിവാക്കും.",
  "Display Order": "പ്രദർശന ക്രമം",
  "e.g. Basic, HRA, Special Allowance": "ഉദാ. അടിസ്ഥാന ശമ്പളം, HRA, സ്പെഷ്യൽ അലവൻസ്",
  "e.g. Standard, Management, Executive": "ഉദാ. സ്റ്റാൻഡേർഡ്, മാനേജ്മെന്റ്, എക്സിക്യൂട്ടീവ്",
  "Earning": "വരുമാനം",
  "Enabling {name} affects {count} employee(s). Previously stored overrides will not be reused; a fresh value must be entered where required.": "{name} പ്രവർത്തനക്ഷമമാക്കുന്നത് {count} ജീവനക്കാരെ ബാധിക്കും. മുമ്പ് സൂക്ഷിച്ച മാറ്റങ്ങൾ വീണ്ടും ഉപയോഗിക്കില്ല; ആവശ്യമുള്ളിടത്ത് പുതിയ മൂല്യം നൽകണം.",
  "Enter a non-negative value.": "നെഗറ്റീവ് അല്ലാത്ത മൂല്യം നൽകുക.",
