  "Salary structure removed from active use. Payroll history is preserved.": "ശമ്പള ഘടന സജീവ ഉപയോഗത്തിൽ നിന്ന് നീക്കം ചെയ്തു. പേറോൾ ചരിത്രം സൂക്ഷിച്ചിട്ടുണ്ട്.",
