  "Set up a reusable salary template. You can add earnings, allowances, and deductions after creating it.": "വീണ്ടും ഉപയോഗിക്കാവുന്ന ഒരു ശമ്പള ടെംപ്ലേറ്റ് സജ്ജമാക്കുക. സൃഷ്ടിച്ചതിന് ശേഷം വരുമാനങ്ങൾ, അലവൻസുകൾ, കിഴിവുകൾ എന്നിവ ചേർക്കാം.",
