  "The remaining CTC after other enabled earnings and statutory employer contributions.": "പ്രവർത്തനക്ഷമമാക്കിയ മറ്റ് വരുമാനങ്ങൾക്കും നിയമപരമായ തൊഴിലുടമ വിഹിതങ്ങൾക്കും ശേഷം ബാക്കിയുള്ള CTC.",
  "Use this structure as the default when setting up employee compensation.": "ജീവനക്കാരുടെ ശമ്പളം സജ്ജമാക്കുമ്പോൾ ഈ ഘടന ഡിഫോൾട്ടായി ഉപയോഗിക്കുക.",
  "{label} must be between 0 and 100.": "{label} 0-നും 100-നും ഇടയിലായിരിക്കണം.",
  "A config for this state may already exist.": "ഈ സംസ്ഥാനത്തിന് ഇതിനകം ഒരു കോൺഫിഗറേഷൻ ഉണ്ടായിരിക്കാം.",
  "An employee averaging at or below the daily wage above is exempt from their own ESI share. The employer share is still due.": "മുകളിലെ ദിവസ വേതനത്തിനോ അതിൽ താഴെയോ ശരാശരി ലഭിക്കുന്ന ജീവനക്കാരൻ സ്വന്തം ESI വിഹിതത്തിൽ നിന്ന് ഒഴിവാണ്. തൊഴിലുടമയുടെ വിഹിതം ഇപ്പോഴും നൽകണം.",
  "Config created.": "കോൺഫിഗറേഷൻ സൃഷ്ടിച്ചു.",
