  "Choose which rows appear in the employee Basic Pay editor. Hiding a row changes visibility only; it remains included in calculations and existing pay records.": "ജീവനക്കാരുടെ അടിസ്ഥാന ശമ്പള എഡിറ്ററിൽ ഏതൊക്കെ വരികൾ കാണിക്കണമെന്ന് തിരഞ്ഞെടുക്കുക. ഒരു വരി മറയ്ക്കുന്നത് ദൃശ്യതയെ മാത്രമേ മാറ്റൂ; അത് കണക്കുകൂട്ടലുകളിലും നിലവിലെ ശമ്പള രേഖകളിലും തുടർന്നും ഉൾപ്പെടും.",
