  "Search address": "വിലാസം തിരയുക",
  "Select a saved location or capture a new one to see its details here.": "വിശദാംശങ്ങൾ ഇവിടെ കാണാൻ സേവ് ചെയ്ത ലൊക്കേഷൻ തിരഞ്ഞെടുക്കുകയോ പുതിയത് പകർത്തുകയോ ചെയ്യുക.",
  "Select a saved location, capture your current one, or search an address before submitting — this is what your clock-in will be checked against on WFH days.": "സമർപ്പിക്കുന്നതിന് മുമ്പ് സേവ് ചെയ്ത ലൊക്കേഷൻ തിരഞ്ഞെടുക്കുക, നിലവിലുള്ളത് പകർത്തുക, അല്ലെങ്കിൽ വിലാസം തിരയുക — WFH ദിവസങ്ങളിൽ നിങ്ങളുടെ ക്ലോക്ക്-ഇൻ ഇതുമായാണ് താരതമ്യം ചെയ്യുന്നത്.",
  "Source": "ഉറവിടം",
