  "View My Requests": "എന്റെ അപേക്ഷകൾ കാണുക",
  "Why do you need to work from home? Your approver will read this.": "എന്തുകൊണ്ടാണ് നിങ്ങൾക്ക് വർക്ക് ഫ്രം ഹോം വേണ്ടത്? നിങ്ങളുടെ അംഗീകരിക്കുന്നയാൾ ഇത് വായിക്കും.",
  "Your browser doesn't support location capture.": "നിങ്ങളുടെ ബ്രൗസർ ലൊക്കേഷൻ പകർത്തലിനെ പിന്തുണയ്ക്കുന്നില്ല.",
  "Your existing requests are listed under": "നിങ്ങളുടെ നിലവിലെ അപേക്ഷകൾ ഇതിന് കീഴിൽ കാണാം",
