  "Address matches": "വിലാസം യോജിക്കുന്നത്",
  "House / street, area, city, pincode": "വീട് / തെരുവ്, പ്രദേശം, നഗരം, പിൻകോഡ്",
  "No match found. Try adding the area, city or pincode.": "യോജിക്കുന്നത് കണ്ടെത്തിയില്ല. പ്രദേശം, നഗരം അല്ലെങ്കിൽ പിൻകോഡ് ചേർത്ത് നോക്കുക.",
  "The address search failed. Please try again.": "വിലാസ തിരയൽ പരാജയപ്പെട്ടു. ദയവായി വീണ്ടും ശ്രമിക്കുക.",
  "Type at least the street, area and city.": "കുറഞ്ഞത് തെരുവ്, പ്രദേശം, നഗരം എന്നിവ ടൈപ്പ് ചെയ്യുക.",
  "An approved request can't be cancelled from here. If your plans changed, ask your manager or HR.": "അംഗീകരിച്ച അപേക്ഷ ഇവിടെ നിന്ന് റദ്ദാക്കാൻ കഴിയില്ല. നിങ്ങളുടെ പദ്ധതികൾ മാറിയെങ്കിൽ മാനേജറോടോ എച്ച്ആറിനോടോ ആവശ്യപ്പെടുക.",
  "Cancel this work-from-home request?": "ഈ വർക്ക് ഫ്രം ഹോം അപേക്ഷ റദ്ദാക്കണോ?",
