  "You can punch from any location on these days.": "ഈ ദിവസങ്ങളിൽ നിങ്ങൾക്ക് ഏത് സ്ഥലത്തുനിന്നും പഞ്ച് ചെയ്യാം.",
  "You must punch near this location. If you have moved, ask your manager or HR to allow punching from any location.": "ഈ ലൊക്കേഷന് സമീപത്തുനിന്ന് പഞ്ച് ചെയ്യണം. നിങ്ങൾ സ്ഥലം മാറിയെങ്കിൽ ഏത് സ്ഥലത്തുനിന്നും പഞ്ച് ചെയ്യാൻ അനുവദിക്കണമെന്ന് മാനേജറോടോ എച്ച്ആറിനോടോ ആവശ്യപ്പെടുക.",
