  "{count} family members": "{count} കുടുംബാംഗങ്ങൾ",
  "A nominee is picked from the family list, and there is nobody in it yet. Add a family member with a name above, then add the nominee.": "നോമിനിയെ കുടുംബ പട്ടികയിൽ നിന്നാണ് തിരഞ്ഞെടുക്കുന്നത്, അതിൽ ഇതുവരെ ആരുമില്ല. മുകളിൽ പേരോടെ ഒരു കുടുംബാംഗത്തെ ചേർക്കുക, തുടർന്ന് നോമിനിയെ ചേർക്കുക.",
  "Add a family member with a name above before adding a nominee.": "നോമിനിയെ ചേർക്കുന്നതിന് മുമ്പ് മുകളിൽ പേരോടെ ഒരു കുടുംബാംഗത്തെ ചേർക്കുക.",
  "Add the people who depend on the employee or who may be nominated below. A person is added once and can be picked as a nominee.": "ജീവനക്കാരനെ ആശ്രയിക്കുന്നവരെയോ നോമിനിയാക്കാൻ സാധ്യതയുള്ളവരെയോ താഴെ ചേർക്കുക. ഒരാളെ ഒരു തവണ ചേർത്താൽ മതി, അവരെ നോമിനിയായി തിരഞ്ഞെടുക്കാം.",
  "Another {relationship} is already listed.": "മറ്റൊരു {relationship} ഇതിനകം പട്ടികയിലുണ്ട്.",
  "Each scheme's shares should add up to 100% across its nominees. Pick nominees from the family list above.": "ഓരോ പദ്ധതിയുടെയും വിഹിതങ്ങൾ അതിലെ നോമിനികളിലായി ആകെ 100% ആകണം. മുകളിലെ കുടുംബ പട്ടികയിൽ നിന്ന് നോമിനികളെ തിരഞ്ഞെടുക്കുക.",
  "EPF / Gratuity nomination": "EPF / ഗ്രാറ്റ്വിറ്റി നോമിനേഷൻ",
  "No family members yet. This is optional; use the buttons above to add someone.": "ഇതുവരെ കുടുംബാംഗങ്ങളില്ല. ഇത് ഓപ്ഷണലാണ്; ആരെയെങ്കിലും ചേർക്കാൻ മുകളിലെ ബട്ടണുകൾ ഉപയോഗിക്കുക.",
  "Quick add": "പെട്ടെന്ന് ചേർക്കുക",
