  "on any section to go back and change it — nothing is sent to HR until you press": "ഏതെങ്കിലും വിഭാഗത്തിൽ ക്ലിക്ക് ചെയ്ത് തിരികെ പോയി മാറ്റം വരുത്താം — നിങ്ങൾ അമർത്തുന്നതുവരെ എച്ച്ആറിന് ഒന്നും അയയ്ക്കില്ല",
  "Optional — not submitted": "ഓപ്ഷണൽ — സമർപ്പിച്ചിട്ടില്ല",
