  "Review everything below before submitting. Use": "സമർപ്പിക്കുന്നതിന് മുമ്പ് താഴെയുള്ളതെല്ലാം പരിശോധിക്കുക. ഉപയോഗിക്കുക",
  "{name} preview": "{name} പ്രിവ്യൂ",
  "Checked against every other employee before the upload goes through — enter it first.": "അപ്ലോഡ് പൂർത്തിയാക്കുന്നതിന് മുമ്പ് മറ്റെല്ലാ ജീവനക്കാരുമായി പരിശോധിക്കും — ആദ്യം ഇത് നൽകുക.",
  "Drag and drop a file onto any row below, or click Upload. Accepted: PDF, JPG, PNG · Max 5 MB each.": "താഴെയുള്ള ഏതെങ്കിലും വരിയിലേക്ക് ഫയൽ വലിച്ചിടുക, അല്ലെങ്കിൽ അപ്ലോഡ് ക്ലിക്ക് ചെയ്യുക. സ്വീകരിക്കുന്നത്: PDF, JPG, PNG · ഓരോന്നിനും പരമാവധി 5 MB.",
