  "Only PDF, JPG, and PNG files are accepted.": "PDF, JPG, PNG ഫയലുകൾ മാത്രമേ സ്വീകരിക്കൂ.",
  "PAN Number": "PAN നമ്പർ",
  "Remove this document": "ഈ ഡോക്യുമെന്റ് നീക്കം ചെയ്യുക",
  "Face ID approved": "Face ID അംഗീകരിച്ചു",
  "Face ID not yet registered": "Face ID ഇതുവരെ രജിസ്റ്റർ ചെയ്തിട്ടില്ല",
