  "You won't be able to submit your onboarding profile until this step is complete.": "ഈ ഘട്ടം പൂർത്തിയാകുന്നതുവരെ നിങ്ങളുടെ ഓൺബോർഡിംഗ് പ്രൊഫൈൽ സമർപ്പിക്കാൻ കഴിയില്ല.",
  "Your organisation requires a registered face ID for web clock-in/out. Register once here — we run a quick liveness check to confirm it's really you, and it takes effect immediately.": "വെബ് ക്ലോക്ക്-ഇൻ/ഔട്ടിന് നിങ്ങളുടെ സ്ഥാപനം രജിസ്റ്റർ ചെയ്ത Face ID ആവശ്യപ്പെടുന്നു. ഇവിടെ ഒരു തവണ രജിസ്റ്റർ ചെയ്യുക — അത് നിങ്ങൾ തന്നെയാണെന്ന് ഉറപ്പാക്കാൻ ഞങ്ങൾ ഒരു ചെറിയ ലൈവ്നെസ് പരിശോധന നടത്തും, ഇത് ഉടൻ പ്രാബല്യത്തിൽ വരും.",
  "Your organisation requires a registered face ID for web clock-in/out. Register once here — we run a quick liveness check to confirm it's really you, then send it to HR for approval.": "വെബ് ക്ലോക്ക്-ഇൻ/ഔട്ടിന് നിങ്ങളുടെ സ്ഥാപനം രജിസ്റ്റർ ചെയ്ത Face ID ആവശ്യപ്പെടുന്നു. ഇവിടെ ഒരു തവണ രജിസ്റ്റർ ചെയ്യുക — അത് നിങ്ങൾ തന്നെയാണെന്ന് ഉറപ്പാക്കാൻ ഞങ്ങൾ ഒരു ചെറിയ ലൈവ്നെസ് പരിശോധന നടത്തി, തുടർന്ന് അംഗീകാരത്തിനായി എച്ച്ആറിന് അയയ്ക്കും.",
