  "Your progress has been saved.": "നിങ്ങളുടെ പുരോഗതി സേവ് ചെയ്തിട്ടുണ്ട്.",
  "A bank detail change you submitted is awaiting HR review — your previous details remain active for payroll until it's approved.": "നിങ്ങൾ സമർപ്പിച്ച ബാങ്ക് വിവര മാറ്റം എച്ച്ആർ അവലോകനത്തിനായി കാത്തിരിക്കുന്നു — അംഗീകരിക്കുന്നതുവരെ പേറോളിന് നിങ്ങളുടെ മുൻ വിവരങ്ങൾ തന്നെ ഉപയോഗിക്കും.",
  "Approved — check your email": "അംഗീകരിച്ചു — നിങ്ങളുടെ ഇമെയിൽ പരിശോധിക്കുക",
  "Check Approval Status": "അംഗീകാര നില പരിശോധിക്കുക",
  "Complete Face ID registration (Step 6) before submitting.": "സമർപ്പിക്കുന്നതിന് മുമ്പ് Face ID രജിസ്ട്രേഷൻ (ഘട്ടം 6) പൂർത്തിയാക്കുക.",
  "Complete Face ID registration (Step 6) to enable submission.": "സമർപ്പിക്കാൻ Face ID രജിസ്ട്രേഷൻ (ഘട്ടം 6) പൂർത്തിയാക്കുക.",
  "Complete your profile": "നിങ്ങളുടെ പ്രൊഫൈൽ പൂർത്തിയാക്കുക",
  "Could not remove this document. Please try again.": "ഈ ഡോക്യുമെന്റ് നീക്കം ചെയ്യാനായില്ല. ദയവായി വീണ്ടും ശ്രമിക്കുക.",
  "Enter your PAN number before uploading the PAN card.": "PAN കാർഡ് അപ്ലോഡ് ചെയ്യുന്നതിന് മുമ്പ് നിങ്ങളുടെ PAN നമ്പർ നൽകുക.",
  "Fill in your details to get started. Your information is kept secure.": "ആരംഭിക്കാൻ നിങ്ങളുടെ വിവരങ്ങൾ പൂരിപ്പിക്കുക. നിങ്ങളുടെ വിവരങ്ങൾ സുരക്ഷിതമായി സൂക്ഷിക്കുന്നു.",
  "HR has approved your onboarding.": "എച്ച്ആർ നിങ്ങളുടെ ഓൺബോർഡിംഗ് അംഗീകരിച്ചു.",
  "HR sent this back for corrections:": "തിരുത്തലുകൾക്കായി എച്ച്ആർ ഇത് തിരിച്ചയച്ചു:",
  "Name is required for every family member — remove any blank ones, or fill them in.": "ഓരോ കുടുംബാംഗത്തിനും പേര് ആവശ്യമാണ് — ഒഴിഞ്ഞവ നീക്കം ചെയ്യുക, അല്ലെങ്കിൽ പൂരിപ്പിക്കുക.",
  "Not saved yet. Check your connection; Save & Continue will retry": "ഇതുവരെ സേവ് ചെയ്തിട്ടില്ല. നിങ്ങളുടെ കണക്ഷൻ പരിശോധിക്കുക; സേവ് ചെയ്ത് തുടരുക വീണ്ടും ശ്രമിക്കും",
  "Please fill in: {fields}": "ദയവായി പൂരിപ്പിക്കുക: {fields}",
  "Please review and resubmit — contact HR for details.": "ദയവായി അവലോകനം ചെയ്ത് വീണ്ടും സമർപ്പിക്കുക — വിശദാംശങ്ങൾക്ക് എച്ച്ആറിനെ ബന്ധപ്പെടുക.",
  "Profile Submitted!": "പ്രൊഫൈൽ സമർപ്പിച്ചു!",
  "Save Draft": "ഡ്രാഫ്റ്റ് സേവ് ചെയ്യുക",
  "Saved successfully.": "വിജയകരമായി സേവ് ചെയ്തു.",
  "Select a family member for every nominee — remove any incomplete ones, or fill them in.": "ഓരോ നോമിനിക്കും ഒരു കുടുംബാംഗത്തെ തിരഞ്ഞെടുക്കുക — അപൂർണ്ണമായവ നീക്കം ചെയ്യുക, അല്ലെങ്കിൽ പൂരിപ്പിക്കുക.",
  "Select an asset type for every entry — remove any incomplete ones, or fill them in.": "ഓരോ എൻട്രിക്കും ഒരു ആസ്തി തരം തിരഞ്ഞെടുക്കുക — അപൂർണ്ണമായവ നീക്കം ചെയ്യുക, അല്ലെങ്കിൽ പൂരിപ്പിക്കുക.",
  "Still awaiting HR review — check back later, or wait for the email notification.": "ഇപ്പോഴും എച്ച്ആർ അവലോകനത്തിനായി കാത്തിരിക്കുന്നു — പിന്നീട് പരിശോധിക്കുക, അല്ലെങ്കിൽ ഇമെയിൽ അറിയിപ്പിനായി കാത്തിരിക്കുക.",
  "We have emailed you a link to set your password and activate your account.": "നിങ്ങളുടെ പാസ്‌വേഡ് സജ്ജമാക്കാനും അക്കൗണ്ട് സജീവമാക്കാനും ഉള്ള ഒരു ലിങ്ക് ഞങ്ങൾ നിങ്ങൾക്ക് ഇമെയിൽ ചെയ്തിട്ടുണ്ട്.",
  "You can close this tab and continue from the email.": "നിങ്ങൾക്ക് ഈ ടാബ് അടച്ച് ഇമെയിലിൽ നിന്ന് തുടരാം.",
  "You can close this tab. We will notify you by email when approved.": "നിങ്ങൾക്ക് ഈ ടാബ് അടയ്ക്കാം. അംഗീകരിക്കുമ്പോൾ ഞങ്ങൾ ഇമെയിൽ വഴി അറിയിക്കും.",
  "You will receive access once approved.": "അംഗീകരിച്ചാൽ നിങ്ങൾക്ക് ആക്സസ് ലഭിക്കും.",
  "Your onboarding details have been sent for HR review.": "നിങ്ങളുടെ ഓൺബോർഡിംഗ് വിവരങ്ങൾ എച്ച്ആർ അവലോകനത്തിനായി അയച്ചിട്ടുണ്ട്.",
  "Opening your onboarding…": "നിങ്ങളുടെ ഓൺബോർഡിംഗ് തുറക്കുന്നു…",
  "This link can't be used": "ഈ ലിങ്ക് ഉപയോഗിക്കാനാവില്ല",
  "Ask HR to reset your password again, or": "നിങ്ങളുടെ പാസ്‌വേഡ് വീണ്ടും റീസെറ്റ് ചെയ്യാൻ എച്ച്ആറിനോട് ആവശ്യപ്പെടുക, അല്ലെങ്കിൽ",
  "Checking your reset link…": "നിങ്ങളുടെ റീസെറ്റ് ലിങ്ക് പരിശോധിക്കുന്നു…",
  "Log in with your new password to continue.": "തുടരാൻ നിങ്ങളുടെ പുതിയ പാസ്‌വേഡ് ഉപയോഗിച്ച് ലോഗിൻ ചെയ്യുക.",
  "Password set": "പാസ്‌വേഡ് സജ്ജമാക്കി",
  "Set new password": "പുതിയ പാസ്‌വേഡ് സജ്ജമാക്കുക",
  "Setting password…": "പാസ്‌വേഡ് സജ്ജമാക്കുന്നു…",
