  "Your password was reset by HR. Set a new one to continue signing in as": "നിങ്ങളുടെ പാസ്‌വേഡ് എച്ച്ആർ റീസെറ്റ് ചെയ്തു. ഇനിപ്പറയുന്നയാളായി സൈൻ ഇൻ ചെയ്യുന്നത് തുടരാൻ പുതിയൊരെണ്ണം സജ്ജമാക്കുക",
  "Choose someone only if L1 should differ from what the approval rule gives.": "അംഗീകാര നിയമം നൽകുന്നതിൽ നിന്ന് L1 വ്യത്യസ്തമായിരിക്കണമെങ്കിൽ മാത്രം ഒരാളെ തിരഞ്ഞെടുക്കുക.",
  "Could not load the list of people. Try again in a moment.": "ആളുകളുടെ പട്ടിക ലോഡ് ചെയ്യാനായില്ല. അൽപ്പസമയം കഴിഞ്ഞ് വീണ്ടും ശ്രമിക്കുക.",
