  "These people approve your leave requests. Ask HR if something here is wrong or missing.": "ഈ ആളുകളാണ് നിങ്ങളുടെ ലീവ് അപേക്ഷകൾ അംഗീകരിക്കുന്നത്. ഇവിടെ എന്തെങ്കിലും തെറ്റോ വിട്ടുപോയതോ ഉണ്ടെങ്കിൽ എച്ച്ആറിനോട് ചോദിക്കുക.",
