  "No health signals available for your role.": "നിങ്ങളുടെ റോളിന് ആരോഗ്യ സൂചനകളൊന്നും ലഭ്യമല്ല.",
  "No holidays configured for {year} — import required": "{year}-ലേക്ക് അവധി ദിനങ്ങളൊന്നും സജ്ജമാക്കിയിട്ടില്ല — ഇംപോർട്ട് ആവശ്യമാണ്",
  "Platform safeguards": "പ്ലാറ്റ്ഫോം സുരക്ഷാ സംവിധാനങ്ങൾ",
