  "Add a profile photo": "പ്രൊഫൈൽ ഫോട്ടോ ചേർക്കുക",
  "Allow camera access for this site in your browser's settings, then try again — or upload a photo from your device instead.": "നിങ്ങളുടെ ബ്രൗസർ സെറ്റിംഗ്സിൽ ഈ സൈറ്റിന് ക്യാമറ ആക്സസ് അനുവദിച്ച ശേഷം വീണ്ടും ശ്രമിക്കുക — അല്ലെങ്കിൽ പകരം നിങ്ങളുടെ ഡിവൈസിൽ നിന്ന് ഒരു ഫോട്ടോ അപ്ലോഡ് ചെയ്യുക.",
