  "Usage-based (~$0.10 per 1,000 emails) — cheapest option once you're sending real volume.": "ഉപയോഗം അടിസ്ഥാനമാക്കിയുള്ളത് (1,000 ഇമെയിലിന് ~$0.10) — വലിയ അളവിൽ അയയ്ക്കുമ്പോൾ ഏറ്റവും ചെലവു കുറഞ്ഞ മാർഗം.",
  "Use a Google App Password, not your normal account password.": "സാധാരണ അക്കൗണ്ട് പാസ്‌വേഡ് അല്ല, Google ആപ്പ് പാസ്‌വേഡ് ഉപയോഗിക്കുക.",
  "Use smtp.zoho.in / smtp.zoho.eu instead if your Zoho account's data center is India or Europe.": "നിങ്ങളുടെ Zoho അക്കൗണ്ടിന്റെ ഡാറ്റ സെന്റർ ഇന്ത്യയിലോ യൂറോപ്പിലോ ആണെങ്കിൽ പകരം smtp.zoho.in / smtp.zoho.eu ഉപയോഗിക്കുക.",
  "Use the server's own built-in mail system — no external credentials needed.": "സെർവറിന്റെ സ്വന്തം ഇൻബിൽറ്റ് മെയിൽ സിസ്റ്റം ഉപയോഗിക്കുക — ബാഹ്യ ക്രെഡൻഷ്യലുകൾ ആവശ്യമില്ല.",
  "User Restriction": "ഉപയോക്തൃ നിയന്ത്രണം",
  "Username is literally \"resend\" — the password field is your Resend API key, not an account password.": "ഉപയോക്തൃനാമം അക്ഷരാർത്ഥത്തിൽ \"resend\" തന്നെയാണ് — പാസ്‌വേഡ് ഫീൽഡ് നിങ്ങളുടെ Resend API കീ ആണ്, അക്കൗണ്ട് പാസ്‌വേഡ് അല്ല.",
  "Users": "ഉപയോക്താക്കൾ",
  "View all system actions and changes": "സിസ്റ്റത്തിലെ എല്ലാ നടപടികളും മാറ്റങ്ങളും കാണുക",
