  "Whether assessments are timed globally and the default maximum duration": "വിലയിരുത്തലുകൾക്ക് ആഗോളമായി സമയപരിധി ഉണ്ടോ എന്നും സ്ഥിരസ്ഥിതി പരമാവധി ദൈർഘ്യവും",
  "Who approves leave, expenses, resignation and loans": "ലീവ്, ചെലവുകൾ, രാജി, വായ്പകൾ എന്നിവ ആര് അംഗീകരിക്കുന്നു",
  "Who you are and who can do what": "നിങ്ങൾ ആരാണെന്നും ആർക്ക് എന്ത് ചെയ്യാമെന്നും",
  "Wish": "ആശംസ",
  "Worker type": "തൊഴിലാളി തരം",
  "Zoho Mail": "Zoho Mail",
  "Could not undo the change.": "മാറ്റം പഴയപടിയാക്കാനായില്ല.",
  "Failed to save attendance settings.": "ഹാജർ സെറ്റിംഗ്സ് സേവ് ചെയ്യാനായില്ല.",
  "Basic pay saved — ₹{amount} per annum, effective {date}.": "അടിസ്ഥാന ശമ്പളം സേവ് ചെയ്തു — പ്രതിവർഷം ₹{amount}, {date} മുതൽ പ്രാബല്യത്തിൽ.",
  "Could not save this pay record.": "ഈ ശമ്പള രേഖ സേവ് ചെയ്യാനായില്ല.",
  "Enter an annual CTC greater than zero.": "പൂജ്യത്തേക്കാൾ കൂടുതലുള്ള വാർഷിക CTC നൽകുക.",
  "Must be on or after {date}.": "{date}-ന് അല്ലെങ്കിൽ അതിന് ശേഷമായിരിക്കണം.",
  "Updating the record in force from {date}.": "{date} മുതൽ പ്രാബല്യത്തിലുള്ള രേഖ അപ്ഡേറ്റ് ചെയ്യുന്നു.",
  "Location access is required for office punch in/out. Please allow location in your browser settings.": "ഓഫീസ് പഞ്ച് ഇൻ/ഔട്ടിന് ലൊക്കേഷൻ ആക്സസ് ആവശ്യമാണ്. ദയവായി ബ്രൗസർ സെറ്റിംഗ്സിൽ ലൊക്കേഷൻ അനുവദിക്കുക.",
  "Location access is required for work-from-home punch in/out. Please allow location in your browser settings.": "വർക്ക് ഫ്രം ഹോം പഞ്ച് ഇൻ/ഔട്ടിന് ലൊക്കേഷൻ ആക്സസ് ആവശ്യമാണ്. ദയവായി ബ്രൗസർ സെറ്റിംഗ്സിൽ ലൊക്കേഷൻ അനുവദിക്കുക.",
  "Please register your Face ID first (Profile > Register My Face), then come back to punch in.": "ദയവായി ആദ്യം നിങ്ങളുടെ Face ID രജിസ്റ്റർ ചെയ്യുക (പ്രൊഫൈൽ > എന്റെ മുഖം രജിസ്റ്റർ ചെയ്യുക), തുടർന്ന് പഞ്ച് ഇൻ ചെയ്യാൻ തിരികെ വരിക.",
  "Punch failed. Please try again.": "പഞ്ച് പരാജയപ്പെട്ടു. ദയവായി വീണ്ടും ശ്രമിക്കുക.",
  "Punched in successfully.": "പഞ്ച് ഇൻ വിജയകരമായി പൂർത്തിയായി.",
  "Punched out successfully.": "പഞ്ച് ഔട്ട് വിജയകരമായി പൂർത്തിയായി.",
  "Too many failed face verification attempts. Please wait {time} before trying again.": "മുഖ പരിശോധന വളരെയധികം തവണ പരാജയപ്പെട്ടു. വീണ്ടും ശ്രമിക്കുന്നതിന് മുമ്പ് ദയവായി {time} കാത്തിരിക്കുക.",
  "Unable to determine your location. Please check your device's location settings and try again.": "നിങ്ങളുടെ ലൊക്കേഷൻ കണ്ടെത്താനായില്ല. ദയവായി ഡിവൈസിന്റെ ലൊക്കേഷൻ സെറ്റിംഗ്സ് പരിശോധിച്ച് വീണ്ടും ശ്രമിക്കുക.",
  "You are outside the allowed location for this branch.": "ഈ ബ്രാഞ്ചിന് അനുവദിച്ച സ്ഥലത്തിന് പുറത്താണ് നിങ്ങൾ.",
  "Your browser does not support location access.": "നിങ്ങളുടെ ബ്രൗസർ ലൊക്കേഷൻ ആക്സസ് പിന്തുണയ്ക്കുന്നില്ല.",
  "Choose the filled template first.": "ആദ്യം പൂരിപ്പിച്ച ടെംപ്ലേറ്റ് തിരഞ്ഞെടുക്കുക.",
  "Could not cancel the import.": "ഇമ്പോർട്ട് റദ്ദാക്കാനായില്ല.",
  "Could not create the error file.": "പിശക് ഫയൽ സൃഷ്ടിക്കാനായില്ല.",
  "Could not download the error report.": "പിശക് റിപ്പോർട്ട് ഡൗൺലോഡ് ചെയ്യാനായില്ല.",
  "Could not download the template.": "ടെംപ്ലേറ്റ് ഡൗൺലോഡ് ചെയ്യാനായില്ല.",
  "Could not open that import.": "ആ ഇമ്പോർട്ട് തുറക്കാനായില്ല.",
