  "The connection was lost, so the outcome is unknown. Press Confirm again: this import cannot be applied twice.": "കണക്ഷൻ നഷ്ടപ്പെട്ടതിനാൽ ഫലം അറിയില്ല. വീണ്ടും സ്ഥിരീകരിക്കുക അമർത്തുക: ഈ ഇമ്പോർട്ട് രണ്ടുതവണ പ്രയോഗിക്കാനാവില്ല.",
  "The file could not be checked. Nothing was imported.": "ഫയൽ പരിശോധിക്കാനായില്ല. ഒന്നും ഇമ്പോർട്ട് ചെയ്തിട്ടില്ല.",
  "The import was rejected. Nothing was created.": "ഇമ്പോർട്ട് നിരസിച്ചു. ഒന്നും സൃഷ്ടിച്ചിട്ടില്ല.",
  "{percent}% of headcount · {count} on probation": "ആകെ ജീവനക്കാരുടെ {percent}% · {count} പേർ പ്രൊബേഷനിൽ",
  "across {count} org units": "{count} സ്ഥാപന യൂണിറ്റുകളിലായി",
  "all assigned a reporting manager": "എല്ലാവർക്കും റിപ്പോർട്ടിംഗ് മാനേജരെ നൽകിയിട്ടുണ്ട്",
  "Are you sure you want to activate {name}?": "{name} സജീവമാക്കണമെന്ന് ഉറപ്പാണോ?",
  "Are you sure you want to deactivate {name}?": "{name} നിർജ്ജീവമാക്കണമെന്ന് ഉറപ്പാണോ?",
  "Could not export the employee directory. Please try again.": "ജീവനക്കാരുടെ ഡയറക്ടറി എക്സ്പോർട്ട് ചെയ്യാനായില്ല. ദയവായി വീണ്ടും ശ്രമിക്കുക.",
  "Could not load employees. Please refresh.": "ജീവനക്കാരെ ലോഡ് ചെയ്യാനായില്ല. ദയവായി റിഫ്രഷ് ചെയ്യുക.",
  "Employee directory exported.": "ജീവനക്കാരുടെ ഡയറക്ടറി എക്സ്പോർട്ട് ചെയ്തു.",
  "exit clearance opens automatically": "എക്സിറ്റ് ക്ലിയറൻസ് സ്വയമേവ തുറക്കും",
