  "Choose a rating from 1 to 5.": "1 മുതൽ 5 വരെ ഒരു റേറ്റിംഗ് തിരഞ്ഞെടുക്കുക.",
  "Choose Recommend, Undecided or Do not recommend.": "ശുപാർശ ചെയ്യുന്നു, തീരുമാനിച്ചിട്ടില്ല, അല്ലെങ്കിൽ ശുപാർശ ചെയ്യുന്നില്ല എന്നിവയിൽ ഒന്ന് തിരഞ്ഞെടുക്കുക.",
  "Could not save your feedback.": "നിങ്ങളുടെ ഫീഡ്ബാക്ക് സേവ് ചെയ്യാനായില്ല.",
  "Write at least {count} characters of comments.": "കുറഞ്ഞത് {count} അക്ഷരങ്ങളുള്ള അഭിപ്രായം എഴുതുക.",
  "Could not resend the onboarding email.": "ഓൺബോർഡിംഗ് ഇമെയിൽ വീണ്ടും അയയ്ക്കാനായില്ല.",
  "Onboarding email resent.": "ഓൺബോർഡിംഗ് ഇമെയിൽ വീണ്ടും അയച്ചു.",
